  "${cat_bin}" > "${scratch_dir}/native/validate-schema.py" <<'AGENT_AUTH_E695311683A398F9FCFC'
#!/usr/bin/env python3
"""Validate an exact staged JSON value without resolving network references."""
import json
from pathlib import Path
import sys
from jsonschema import validators
from referencing import Registry, Resource
from referencing.jsonschema import DRAFT202012

harness, candidate = sys.argv[1:]
schema_path = Path(__file__).parent.parent / 'schemas' / f'{harness}.json'
try:
    schema = json.loads(schema_path.read_text())
    value = json.loads(Path(candidate).read_text())
    # The published OpenCode schema adds models.dev autocomplete enums to model
    # strings. Its pinned ConfigV1/AgentV1 runtime schemas accept ANY string,
    # including custom providers. Validate that actual contract offline instead.
    model_strings = Resource.from_contents({'$defs': {'Model': {'type': 'string'}}}, default_specification=DRAFT202012)
    registry = Registry().with_resource('https://models.dev/model-schema.json', model_strings)
    validator = validators.validator_for(schema)(schema, registry=registry)
    error = next(validator.iter_errors(value), None)
    if error is not None:
        # Do not emit jsonschema's message: it can contain credential values.
        print(f'setup failed: {harness} rejected the staged configuration schema ({error.validator})', file=sys.stderr)
        sys.exit(1)
except Exception:
    print(f'setup failed: could not validate the staged {harness} configuration offline', file=sys.stderr)
    sys.exit(1)
