          ]
        },
        "CLAUDE_CODE_ENABLE_PROMPT_SUGGESTION": {
          "type": "string",
          "description": "Enable prompt suggestions",
          "enum": [
            "true",
            "false"
          ]
        },
        "CLAUDE_CODE_ENABLE_SDK_FILE_CHECKPOINTING": {
          "type": "string",
          "description": "Enable file checkpointing for a non-interactive CLI run, so `claude -p --resume <session-id> --rewind-files <checkpoint-uuid>` can rewind files. The Agent SDK sets this internally when enable_file_checkpointing (Python) or enableFileCheckpointing (TypeScript) is enabled; the bare CLI never sets it. Without it, a non-interactive rewind fails with \"File rewinding is not enabled\". See https://code.claude.com/docs/en/agent-sdk/file-checkpointing"
        },
        "CLAUDE_CODE_ENABLE_TASKS": {
          "type": "string",
          "description": "Enable task tracking in non-interactive mode",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_ENABLE_TELEMETRY": {
          "type": "string",
          "description": "Set to 1 to enable telemetry collection. Required for all OpenTelemetry integration. See https://code.claude.com/docs/en/monitoring-usage#common-configuration-variables",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_ENHANCED_TELEMETRY_BETA": {
          "type": "string",
          "description": "Enable the enhanced telemetry (tracing) beta. ENABLE_ENHANCED_TELEMETRY_BETA is also accepted. See https://code.claude.com/docs/en/monitoring-usage#traces-beta",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_EXIT_AFTER_STOP_DELAY": {
          "type": "string",
          "description": "Wait time in milliseconds before auto-exit after stop"
        },
        "CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS": {
          "type": "string",
          "description": "Enable experimental agent teams feature",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_EXTRA_BODY": {
          "type": "string",
          "description": "JSON object to merge into every API request body"
        },
        "CLAUDE_CODE_FILE_READ_MAX_OUTPUT_TOKENS": {
          "type": "string",
          "description": "Token limit for file read operations"
        },
        "CLAUDE_CODE_FORCE_SESSION_PERSISTENCE": {
          "type": "string",
          "description": "Set to 1 to override the automatic exclusion of nested interactive claude TUI sessions from --resume, --continue, up-arrow history, and the claude agents list (requires v2.1.172+). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_FORCE_STRIKETHROUGH": {
          "type": "string",
          "description": "Set to 1 to force strikethrough rendering for ~~text~~ in Claude's responses when the terminal supports it but is not auto-detected, such as over SSH without TERM_PROGRAM forwarded. Without this, undetected terminals show the literal ~~ markers. Requires Claude Code v2.1.186 or later. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_FORCE_SYNC_OUTPUT": {
          "type": "string",
          "description": "Force synchronous output flushing. When set to 1, forces synchronized output on terminals that auto-detection misses (e.g., Emacs eat)",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_FORK_SUBAGENT": {
          "type": "string",
          "description": "Fork subagent processes in non-interactive sessions. See https://github.com/anthropics/claude-code/blob/main/CHANGELOG.md#21120",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_FORWARD_SUBAGENT_TEXT": {
          "type": "string",
          "description": "Set to 1 to emit subagent text and thinking blocks in claude -p --output-format stream-json output, the same behavior as the --forward-subagent-text flag. Use the variable when a harness invokes claude and cannot pass the flag itself. Unlike the flag, which exits with an error outside non-interactive mode with stream-json output, the variable is ignored there so that nested invocations keep working when it is set process-wide. Requires Claude Code v2.1.211 or later. See https://code.claude.com/docs/en/sub-agents",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_GIT_BASH_PATH": {
          "type": "string",
          "description": "Path to Git Bash executable (Windows only)"
        },
        "CLAUDE_CODE_GLOB_HIDDEN": {
          "type": "string",
          "description": "Include dotfiles/hidden files in Glob results",
          "enum": [
            "true",
            "false"
          ]
        },
        "CLAUDE_CODE_GLOB_NO_IGNORE": {
          "type": "string",
          "description": "Don't respect .gitignore rules in Glob results",
          "enum": [
            "true",
            "false"
          ]
        },
        "CLAUDE_CODE_GLOB_TIMEOUT_SECONDS": {
          "type": "string",
          "description": "Glob tool timeout in seconds (default: 20-60)"
        },
        "CLAUDE_CODE_HIDE_CWD": {
          "type": "string",
          "description": "Hide the working directory in the startup logo. See https://github.com/anthropics/claude-code/blob/main/CHANGELOG.md#21126",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_IDE_HOST_OVERRIDE": {
          "type": "string",
          "description": "Override IDE connection address"
        },
        "CLAUDE_CODE_IDE_SKIP_AUTO_INSTALL": {
          "type": "string",
          "description": "Skip automatic IDE extension installation",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_IDE_SKIP_VALID_CHECK": {
          "type": "string",
          "description": "Skip IDE lockfile validation",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS": {
          "type": "string",
          "description": "How many subagents can be running in one session before the Agent tool refuses to spawn another (default: 20). Accepts a positive whole number in plain digits; anything else is ignored, so the variable can adjust the cap but cannot disable it. Requires Claude Code v2.1.217 or later. See https://code.claude.com/docs/en/sub-agents#concurrent-subagent-limit"
        },
        "CLAUDE_CODE_MAX_CONTEXT_TOKENS": {
          "type": "string",
          "description": "Override context window size in tokens"
        },
        "CLAUDE_CODE_MAX_OUTPUT_TOKENS": {
          "type": "string",
          "description": "Maximum output tokens per API request"
        },
        "CLAUDE_CODE_MAX_RETRIES": {
          "type": "string",
          "description": "Maximum API request retry attempts (default: 10)"
        },
        "CLAUDE_CODE_MAX_SUBAGENTS_PER_SESSION": {
          "type": "string",
          "description": "Cap on the number of subagents one session can spawn with the Agent tool (default: 200). When Claude reaches the cap, spawning another subagent fails with an error telling Claude to finish the remaining work directly. Accepts a positive whole number in plain digits with no upper bound; this variable does not take the scientific notation or digit-separator spellings. Anything else is ignored and the default applies, so the cap can be raised but not turned off. Requires Claude Code v2.1.212 or later. See https://code.claude.com/docs/en/sub-agents#session-subagent-limit"
        },
        "CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH": {
          "type": "string",
          "description": "Number of subagent layers allowed below the main conversation (default: 1). At the default, subagents cannot spawn their own subagents; set 2 or higher to allow it. Accepts a positive whole number in plain digits; anything else is ignored, so the limit can be raised but not turned off. Requires Claude Code v2.1.217 or later. See https://code.claude.com/docs/en/sub-agents#let-subagents-spawn-their-own-subagents"
        },
        "CLAUDE_CODE_MAX_TOOL_USE_CONCURRENCY": {
          "type": "string",
          "description": "Maximum parallel tool executions (default: 10)"
        },
        "CLAUDE_CODE_MAX_TURNS": {
          "type": "string",
          "description": "Cap the number of agentic turns when no explicit limit is passed. Equivalent to --max-turns, which takes precedence. A non-positive integer is rejected at startup. See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_CODE_MAX_WEB_SEARCHES_PER_SESSION": {
          "type": "string",
          "description": "Cap on the total number of WebSearch calls one session can make (default: 200). When Claude reaches the cap, further WebSearch calls return a notice telling it to continue with the information it already gathered. Accepts a positive whole number with no upper bound. Anything else is ignored and the default applies, so the cap can be raised but not turned off. Requires Claude Code v2.1.212 or later. See https://code.claude.com/docs/en/tools-reference#websearch-tool-behavior"
        },
        "CLAUDE_CODE_MCP_ALLOWLIST_ENV": {
          "type": "string",
          "description": "Isolate MCP server environments to allowlisted variables",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_MCP_AUTO_BACKGROUND_MS": {
          "type": "string",
          "description": "Elapsed time in milliseconds before a still-running MCP tool call moves to a background task (default: 120000, or 2 minutes). Set to 0 to turn automatic backgrounding off. Requires Claude Code v2.1.212 or later. See https://code.claude.com/docs/en/mcp#automatic-backgrounding-of-long-tool-calls"
        },
        "CLAUDE_CODE_MCP_TOOL_IDLE_TIMEOUT": {
          "type": "string",
          "description": "Idle timeout in milliseconds for MCP tool calls. When a stdio, HTTP, SSE, WebSocket, or claude.ai connector MCP server sends no response and no progress notification for this long, the tool call aborts with an error instead of waiting for the overall MCP_TOOL_TIMEOUT. Overrides the per-transport defaults of 300000 (5 minutes) for network servers and 1800000 (30 minutes) for stdio servers. Set to 0 to disable the idle check. Values below 1000 are raised to one second, and the value is capped at the effective MCP_TOOL_TIMEOUT. A per-server timeout in .mcp.json of at least 1000 raises that server's idle window to at least the timeout value. Does not apply to IDE servers or SDK in-process servers. Requires Claude Code v2.1.187 or later. Before v2.1.203, stdio servers were exempt from the idle timeout. See https://code.claude.com/docs/en/mcp"
        },
        "CLAUDE_CODE_NATIVE_CURSOR": {
          "type": "string",
          "description": "Set to 1 to show the terminal's own cursor at the input caret instead of a drawn block. The cursor respects the terminal's blink, shape, and focus settings. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_NEW_INIT": {
          "type": "string",
          "description": "Use the interactive /init setup flow",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_NO_FLICKER": {
          "type": "string",
          "description": "Enable fullscreen rendering mode to reduce flicker",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_OAUTH_REFRESH_TOKEN": {
          "type": "string",
          "description": "OAuth refresh token"
        },
        "CLAUDE_CODE_OAUTH_SCOPES": {
          "type": "string",
          "description": "OAuth scopes (space-separated)"
        },
        "CLAUDE_CODE_OAUTH_TOKEN": {
          "type": "string",
          "description": "OAuth access token"
        },
        "CLAUDE_CODE_OTEL_CONTENT_MAX_LENGTH": {
          "type": "string",
          "description": "Maximum length of content-bearing OpenTelemetry attributes (model responses, tool content, system prompts, raw API bodies), truncation marker included, in UTF-16 code units (default: 61440, i.e. 60 KB). Raise it only if your telemetry backend accepts attribute values larger than 64 KB, or lower it to cut telemetry volume. Requires Claude Code v2.1.214 or later. See https://code.claude.com/docs/en/monitoring-usage#common-configuration-variables"
        },
        "CLAUDE_CODE_OTEL_DIAG_STDERR": {
          "type": "string",
          "description": "Set to 1 to write OpenTelemetry exporter diagnostic errors to stderr (otherwise shown only with --debug). Requires v2.1.179+. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_OTEL_FLUSH_TIMEOUT_MS": {
          "type": "string",
          "description": "OpenTelemetry span flush timeout in milliseconds (default: 5000)"
        },
        "CLAUDE_CODE_OTEL_HEADERS_HELPER_DEBOUNCE_MS": {
          "type": "string",
          "description": "OpenTelemetry header helper refresh interval in milliseconds"
        },
        "CLAUDE_CODE_OTEL_SHUTDOWN_TIMEOUT_MS": {
          "type": "string",
          "description": "OpenTelemetry shutdown timeout in milliseconds (default: 2000)"
        },
        "CLAUDE_CODE_PACKAGE_MANAGER_AUTO_UPDATE": {
          "type": "string",
          "description": "Enable automatic package manager updates. When set, Claude Code runs the upgrade command in background on Homebrew/WinGet and prompts to restart",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_PERFORCE_MODE": {
          "type": "string",
          "description": "Enable Perforce write protection mode",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_PLUGIN_CACHE_DIR": {
          "type": "string",
          "description": "Override the plugins root directory. Despite the name, this sets the parent directory, not the cache itself: marketplaces and the plugin cache live in subdirectories under this path. Defaults to ~/.claude/plugins. See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_CODE_PLUGIN_GIT_TIMEOUT_MS": {
          "type": "string",
          "description": "Plugin marketplace git operations timeout in milliseconds (default: 120000). See https://github.com/anthropics/claude-code/blob/main/CHANGELOG.md#2151"
        },
        "CLAUDE_CODE_PLUGIN_KEEP_MARKETPLACE_ON_FAILURE": {
          "type": "string",
          "description": "Keep plugin cache on update failure",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_PLUGIN_PREFER_HTTPS": {
          "type": "string",
          "enum": [
            "0",
            "1"
          ],
          "description": "Set to 1 to clone GitHub owner/repo plugin sources over HTTPS instead of SSH. Useful in CI runners, containers, or environments without a configured SSH key for github.com. See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_CODE_PLUGIN_SEED_DIR": {
          "type": "string",
          "description": "Path(s) to pre-populated plugin directories. See https://code.claude.com/docs/en/plugin-marketplaces#pre-populate-plugins-for-containers"
        },
        "CLAUDE_CODE_POWERSHELL_RESPECT_EXECUTION_POLICY": {
          "type": "string",
          "enum": [
            "0",
            "1"
          ],
          "description": "Set to 1 to stop Claude Code from passing -ExecutionPolicy Bypass when spawning PowerShell for tool calls, hooks, and status line commands. By default Claude Code bypasses execution policy so .ps1 scripts work on default-Restricted Windows installs. See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_CODE_PRINT_BG_WAIT_CEILING_MS": {
          "type": "string",
          "description": "Cap, in milliseconds, on how long `claude -p` waits for background subagents at exit (default 10 minutes; set to 0 to wait without limit, added v2.1.182). See https://code.claude.com/docs/en/headless#background-tasks-at-exit"
        },
        "CLAUDE_CODE_PROCESS_WRAPPER": {
          "type": "string",
          "description": "Launch the processes Claude Code starts from its own binary, such as the background service that hosts agent view sessions, through a corporate launcher given as an argv prefix like /opt/corp/launcher. Set it in the env block of user or managed settings, not as a shell export, so the detached background service inherits it; project and local settings cannot set it. Equivalent to the processWrapper setting, which requires Claude Code v2.1.210 or later; this variable takes precedence when both are set. The VS Code extension configures its own launcher separately through its claudeProcessWrapper setting. Ignored on Windows. Requires Claude Code v2.1.208 or later. See https://code.claude.com/docs/en/corporate-launcher"
        },
        "CLAUDE_CODE_PROPAGATE_TRACEPARENT": {
          "type": "string",
          "description": "Propagate the W3C traceparent header on API requests when using a custom ANTHROPIC_BASE_URL. See https://code.claude.com/docs/en/monitoring-usage#traces-beta",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_PROVIDER_MANAGED_BY_HOST": {
          "type": "string",
          "description": "Indicate that the host application manages provider routing",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_PROXY_RESOLVES_HOSTS": {
          "type": "string",
          "description": "Allow proxy to handle DNS resolution",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_REMOTE": {
          "type": "string",
          "description": "Indicates a remote web environment session",
          "enum": [
            "true",
            "false"
          ]
        },
        "CLAUDE_CODE_REMOTE_SESSION_ID": {
          "type": "string",
          "description": "Cloud session identifier for remote sessions"
        },
        "CLAUDE_CODE_RESUME_INTERRUPTED_TURN": {
          "type": "string",
          "description": "Automatically resume from a mid-turn interruption",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_RESUME_INTERRUPTED_TURN_MAX_AGE_MS": {
          "type": "string",
          "description": "Maximum age in milliseconds of the last transcript message for a session that ended mid-turn to continue automatically on resume. When the last message is older than this bound, Claude Code skips both the CLAUDE_CODE_RESUME_INTERRUPTED_TURN automatic resume and the injected CLAUDE_CODE_RESUME_PROMPT continuation message, and the session starts idle so you continue explicitly. Unset or 0 means no bound; a negative or non-numeric value applies a one-hour bound. Spawn scripts for long-running agents can set this so a restart against an old transcript does not re-run a stale prompt. Claude Code sets a one-hour bound itself when it restarts a crashed agent view session that inherited its conversation from an interactive session. Requires Claude Code v2.1.211 or later. See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_CODE_RESUME_PROMPT": {
          "type": "string",
          "description": "Override the continuation message injected when resuming a session that ended mid-turn (default \"Continue from where you left off.\"). An empty string uses the default. See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_CODE_RETRY_WATCHDOG": {
          "type": "string",
          "description": "Set to 1 for unattended sessions (eval harnesses, CI, remote workers) to retry 429/529 capacity errors indefinitely, backing off up to 5 minutes, instead of failing after CLAUDE_CODE_MAX_RETRIES. Requires v2.1.186+. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SAFE_MODE": {
          "type": "string",
          "description": "Set to 1 to start in safe mode: CLAUDE.md, skills, plugins, hooks, MCP servers, custom commands and agents, output styles, workflows, custom themes, custom keybindings, status line and file-suggestion commands, LSP servers, and auto-memory do not load, for troubleshooting a broken configuration. Managed settings policy still applies. Equivalent to passing --safe-mode; directly spawned child processes inherit the variable. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SCRIPT_CAPS": {
          "type": "string",
          "description": "Script invocation limits (JSON object)"
        },
        "CLAUDE_CODE_SCROLL_SPEED": {
          "type": "string",
          "description": "Set the mouse wheel scroll multiplier in fullscreen rendering. Accepts any positive value up to 20, including fractional values below 1 such as 0.5 to slow accelerated trackpad and wheel scrolling in terminals that already amplify wheel events. Set to 3 to match vim if your terminal sends one wheel event per notch without amplification. See https://code.claude.com/docs/en/fullscreen#mouse-wheel-scrolling"
        },
        "CLAUDE_CODE_SESSIONEND_HOOKS_TIMEOUT_MS": {
          "type": "string",
          "description": "Override the time budget in milliseconds for SessionEnd hooks (default 1500, raised up to 60000 by the highest configured per-hook timeout). See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_CODE_SESSION_ID": {
          "type": "string",
          "description": "Set automatically to the current session ID in Bash/PowerShell tool subprocesses, hook command subprocesses, and stdio MCP server subprocesses. Read-only. See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_CODE_SHELL": {
          "type": "string",
          "description": "Override automatic shell detection (e.g., '/bin/zsh', '/bin/bash')"
        },
        "CLAUDE_CODE_SHELL_PREFIX": {
          "type": "string",
          "description": "Command prefix wrapper for shell commands"
        },
        "CLAUDE_CODE_SIMPLE": {
          "type": "string",
          "description": "Minimal mode with core tools only",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SIMPLE_SYSTEM_PROMPT": {
          "type": "string",
          "description": "Use a shortened system prompt",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SKIP_ANTHROPIC_AWS_AUTH": {
          "type": "string",
          "description": "Skip client-side SigV4 authentication for Claude Platform on AWS; use when a proxy or gateway adds authentication before forwarding. See https://code.claude.com/docs/en/claude-platform-on-aws#route-through-a-corporate-proxy",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SKIP_AWS_CRED_CACHE": {
          "type": "string",
          "description": "Set to 1 to turn off the in-process cache of credentials resolved from the AWS default credential provider chain, so Claude Code resolves the chain on every API request. With the cache off, an SSO-backed profile requests credentials from IAM Identity Center on every request. Requires Claude Code v2.1.207 or later. See https://code.claude.com/docs/en/amazon-bedrock#credential-caching-and-resolution-timeout",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SKIP_BEDROCK_AUTH": {
          "type": "string",
          "description": "Skip AWS authentication for Bedrock",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SKIP_FAST_MODE_NETWORK_ERRORS": {
          "type": "string",
          "description": "Set to 1 to treat a failed fast mode availability check as available, for networks that block the check's direct request to api.anthropic.com. Claude Code still honors a \"disabled by your organization\" response. See https://code.claude.com/docs/en/fast-mode#use-fast-mode-behind-proxies-and-llm-gateways",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SKIP_FAST_MODE_ORG_CHECK": {
          "type": "string",
          "description": "Set to 1 to skip the client-side fast mode availability check, for proxies that intercept the check's request rather than refuse it. The API still rejects fast mode requests when your organization has fast mode disabled. See https://code.claude.com/docs/en/fast-mode#use-fast-mode-behind-proxies-and-llm-gateways",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SKIP_FOUNDRY_AUTH": {
          "type": "string",
          "description": "Skip Azure authentication for Foundry",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SKIP_MANTLE_AUTH": {
          "type": "string",
          "description": "Skip AWS authentication for Bedrock Mantle (for example, when using an LLM gateway). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SKIP_PROMPT_HISTORY": {
          "type": "string",
          "description": "Disable transcript writes entirely. See https://code.claude.com/docs/en/settings#environment-variables",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SKIP_VERTEX_AUTH": {
          "type": "string",
          "description": "Skip Google authentication for Google Cloud's Agent Platform",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_STOP_HOOK_BLOCK_CAP": {
          "type": "string",
          "description": "Override the default maximum consecutive Stop hook blocks (default: 8) before the turn ends with a warning. Raise this when a stop hook legitimately needs more than 8 iterations to converge. See https://code.claude.com/docs/en/hooks-guide"
        },
        "CLAUDE_CODE_SUBAGENT_MODEL": {
          "type": "string",
          "description": "Override model used by subagents"
        },
        "CLAUDE_CODE_SUBPROCESS_ENV_SCRUB": {
          "type": "string",
          "description": "Strip credentials from subprocess environments",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SYNC_PLUGIN_INSTALL": {
          "type": "string",
          "description": "Wait synchronously for plugin installation",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SYNC_PLUGIN_INSTALL_TIMEOUT_MS": {
          "type": "string",
          "description": "Timeout in milliseconds for synchronous plugin installation"
        },
        "CLAUDE_CODE_SYNC_SKILLS": {
          "type": "string",
          "description": "Set to 1 to download enabled claude.ai skills into ~/.claude/skills/ before the first query and resync every 10 minutes (non-interactive -p mode only; requires claude.ai auth). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_SYNC_SKILLS_INSTALL_TIMEOUT_MS": {
          "type": "string",
          "description": "Timeout in milliseconds for a mid-session skills resync when CLAUDE_CODE_SYNC_SKILLS is set (default 30000). See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_CODE_SYNC_SKILLS_WAIT_TIMEOUT_MS": {
          "type": "string",
          "description": "Timeout in milliseconds for the first query to wait on the initial skills sync when CLAUDE_CODE_SYNC_SKILLS is set (default 5000). See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_CODE_SYNTAX_HIGHLIGHT": {
          "type": "string",
          "description": "UNDOCUMENTED. Enable syntax highlighting in diffs",
          "enum": [
            "true",
            "false"
          ]
        },
        "CLAUDE_CODE_TASK_LIST_ID": {
          "type": "string",
          "description": "Shared task list identifier for team collaboration"
        },
        "CLAUDE_CODE_TEAM_NAME": {
          "type": "string",
          "description": "Agent team membership name"
        },
        "CLAUDE_CODE_TEAM_TEARDOWN_PARK_TIMEOUT_MS": {
          "type": "string",
          "description": "Override, in milliseconds, how long a non-interactive session waits at exit for its agent team to finish tearing down. Accepts 1000 to 60000; an out-of-range value is ignored and the default of 10000 applies. Requires Claude Code v2.1.206 or later. See https://code.claude.com/docs/en/agent-teams"
        },
        "CLAUDE_CODE_TMPDIR": {
          "type": "string",
          "description": "Override temp directory path"
        },
        "CLAUDE_CODE_TMUX_TRUECOLOR": {
          "type": "string",
          "description": "Allow 24-bit truecolor rendering in tmux",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_USE_ANTHROPIC_AWS": {
          "type": "string",
          "description": "Enable Claude Platform on AWS as the API provider. Bedrock and Foundry take precedence if also set. See https://code.claude.com/docs/en/claude-platform-on-aws#2-configure-claude-code",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_USE_BEDROCK": {
          "type": "string",
          "description": "Enable Amazon Bedrock as the API provider. See https://code.claude.com/docs/en/amazon-bedrock#3-configure-claude-code",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_USE_FOUNDRY": {
          "type": "string",
          "description": "Enable Microsoft Foundry as the API provider. See https://code.claude.com/docs/en/microsoft-foundry#3-configure-claude-code",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_USE_MANTLE": {
          "type": "string",
          "description": "Enable the Mantle endpoint (native Anthropic API shape on Bedrock). See https://code.claude.com/docs/en/amazon-bedrock#enable-mantle",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_USE_NATIVE_FILE_SEARCH": {
          "type": "string",
          "description": "Set to 1 to discover custom commands, subagents, and output styles using Node.js file APIs instead of ripgrep (for environments where the bundled ripgrep is unavailable). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_USE_POWERSHELL_TOOL": {
          "type": "string",
          "description": "Enable PowerShell as default shell for interactive commands (Windows)",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CODE_USE_VERTEX": {
          "type": "string",
          "description": "Enable Google Cloud's Agent Platform as the API provider. See https://code.claude.com/docs/en/google-vertex-ai#4-configure-claude-code",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_CONFIG_DIR": {
          "type": "string",
          "description": "Override the configuration directory (default ~/.claude) where settings, credentials, session history, and plugins are stored. Useful for running multiple accounts side by side. See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_DISABLE_ADOPT": {
          "type": "string",
          "description": "Set to 1 to stop in-flight background work instead of carrying it over when you background a session by pressing ← or with /background. Claude Code asks you to confirm before backgrounding, then stops the tasks that would otherwise carry over. Requires Claude Code v2.1.195 or later. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_EFFORT": {
          "type": "string",
          "enum": [
            "low",
            "medium",
            "high",
            "xhigh",
            "max"
          ],
          "description": "Set automatically in Bash tool subprocesses and hook commands to the active effort level for the turn (low, medium, high, xhigh, or max; ultracode reports as xhigh). Read-only. See https://code.claude.com/docs/en/env-vars"
        },
        "CLAUDE_ENABLE_BYTE_WATCHDOG": {
          "type": "string",
          "description": "Set to 1 to force-enable, or 0 to force-disable, the byte-level streaming idle watchdog that aborts a connection when no bytes arrive within the configured timeout. Enabled by default on direct Anthropic API and Claude Platform on AWS connections. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_ENABLE_BYTE_WATCHDOG_BEDROCK": {
          "type": "string",
          "description": "Set to 1 to enable the byte-level streaming idle watchdog on Amazon Bedrock eventstream responses (off by default). Configure the timeout with CLAUDE_STREAM_IDLE_TIMEOUT_MS. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_ENABLE_STREAM_WATCHDOG": {
          "type": "string",
          "description": "Set to 1 to force-enable, or 0 to force-disable, the event-level streaming idle watchdog. When unset, the watchdog is on by default for all providers (as of v2.1.196; before that the unset default was server-controlled on the direct Anthropic API and off on other providers). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "CLAUDE_ENV_FILE": {
          "type": "string",
          "description": "File path for persisting environment variables across Bash commands"
        },
        "CLAUDE_PID": {
          "type": "string",
          "description": "Claude Code sets this to its own process ID in the subprocesses it spawns: Bash and PowerShell tool commands and hook commands. On Linux, the Bash tool's shell integration uses it to refuse a pkill pattern that would match the Claude Code process itself. Read it from your own scripts to identify or signal the parent Claude Code process deliberately. Requires Claude Code v2.1.214 or later. See https://code.claude.com/docs/en/errors#pkill-pattern-matches-the-claude-code-process"
        },
        "CLAUDE_PROJECT_DIR": {
          "type": "string",
          "description": "Project root directory path (also provided to hooks)"
        },
        "CLAUDE_REMOTE_CONTROL_SESSION_NAME_PREFIX": {
          "type": "string",
          "description": "Prefix for auto-generated Remote Control session names when no explicit name is set. Defaults to the machine hostname, producing names like myhost-graceful-unicorn. See https://code.claude.com/docs/en/remote-control#start-a-remote-control-session"
        },
        "CLAUDE_STREAM_IDLE_TIMEOUT_MS": {
          "type": "string",
          "description": "Timeout in milliseconds before the streaming idle watchdog closes a stalled connection. When set explicitly the minimum is 300000 (5 minutes); lower values are clamped. See https://code.claude.com/docs/en/env-vars"
        },
        "CLOUD_ML_REGION": {
          "type": "string",
          "description": "Google Cloud's Agent Platform region: global, a multi-region location (eu, us), or a specific region (e.g. us-east5). See https://code.claude.com/docs/en/google-vertex-ai#region-configuration"
        },
        "DEBUG": {
          "type": "string",
          "description": "Set to a truthy value (1, true, yes, or on) to enable debug mode, equivalent to --debug. Logs are written to ~/.claude/debug/<session-id>.txt. See https://code.claude.com/docs/en/env-vars"
        },
        "DISABLE_AUTOUPDATER": {
          "type": "string",
          "description": "Set to 1 to disable automatic background updates. Manual claude update still works; use DISABLE_UPDATES to block both. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_AUTO_COMPACT": {
          "type": "string",
          "description": "Set to 1 to disable automatic compaction when approaching the context limit. The manual /compact command remains available. Equivalent to autoCompactEnabled: false. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_COMPACT": {
          "type": "string",
          "description": "Set to 1 to disable all compaction: both automatic compaction and the manual /compact command. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_COST_WARNINGS": {
          "type": "string",
          "description": "Set to 1 to disable cost warning messages. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_DOCTOR_COMMAND": {
          "type": "string",
          "description": "Set to 1 to hide the /doctor command (useful for managed deployments). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_ERROR_REPORTING": {
          "type": "string",
          "description": "Disable Sentry error reporting",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_EXTRA_USAGE_COMMAND": {
          "type": "string",
          "description": "Set to 1 to hide the /usage-credits command for purchasing additional usage beyond rate limits. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_FEEDBACK_COMMAND": {
          "type": "string",
          "description": "Set to 1 to disable the /feedback command. The older name DISABLE_BUG_COMMAND is also accepted. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_GROWTHBOOK": {
          "type": "string",
          "description": "Set to 1 to disable GrowthBook feature-flag fetching and use code defaults for every flag. Telemetry stays on unless DISABLE_TELEMETRY is also set. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_INSTALLATION_CHECKS": {
          "type": "string",
          "description": "Set to 1 to disable installation warnings (use only when manually managing the installation location). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_INSTALL_GITHUB_APP_COMMAND": {
          "type": "string",
          "description": "Set to 1 to hide the /install-github-app command (already hidden on Bedrock, Vertex, or Foundry). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_INTERLEAVED_THINKING": {
          "type": "string",
          "description": "Set to 1 to prevent sending the interleaved-thinking beta header (useful when a gateway or provider does not support interleaved thinking). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_LOGIN_COMMAND": {
          "type": "string",
          "description": "Set to 1 to hide the /login command (useful when authentication is handled externally via API keys or apiKeyHelper). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_LOGOUT_COMMAND": {
          "type": "string",
          "description": "Set to 1 to hide the /logout command. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_PROMPT_CACHING": {
          "type": "string",
          "description": "Disable prompt caching for all models. See https://code.claude.com/docs/en/prompt-caching#disable-prompt-caching",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_PROMPT_CACHING_FABLE": {
          "type": "string",
          "description": "Disable prompt caching for Fable models only. See https://code.claude.com/docs/en/prompt-caching#disable-prompt-caching",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_PROMPT_CACHING_HAIKU": {
          "type": "string",
          "description": "Disable prompt caching for Haiku models only. See https://code.claude.com/docs/en/prompt-caching#disable-prompt-caching",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_PROMPT_CACHING_OPUS": {
          "type": "string",
          "description": "Disable prompt caching for Opus models only. See https://code.claude.com/docs/en/prompt-caching#disable-prompt-caching",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_PROMPT_CACHING_SONNET": {
          "type": "string",
          "description": "Disable prompt caching for Sonnet models only. See https://code.claude.com/docs/en/prompt-caching#disable-prompt-caching",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_TELEMETRY": {
          "type": "string",
          "description": "Set to 1 to opt out of telemetry. Also disables feature-flag fetching (same effect as DISABLE_GROWTHBOOK). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_UPDATES": {
          "type": "string",
          "description": "Block all update paths including manual updates",
          "enum": [
            "0",
            "1"
          ]
        },
        "DISABLE_UPGRADE_COMMAND": {
          "type": "string",
          "description": "Set to 1 to hide the /upgrade command. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "DO_NOT_TRACK": {
          "type": "string",
          "description": "Set to 1 to opt out of telemetry (cross-tool convention; equivalent to DISABLE_TELEMETRY). See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "ENABLE_BETA_TRACING_DETAILED": {
          "type": "string",
          "description": "Emit detailed spans including hook execution when the tracing beta is enabled. See https://code.claude.com/docs/en/monitoring-usage#traces-beta",
          "enum": [
            "0",
            "1"
          ]
        },
        "ENABLE_CLAUDEAI_MCP_SERVERS": {
          "type": "string",
          "description": "Opt in/out of claude.ai MCP servers. See https://github.com/anthropics/claude-code/blob/main/CHANGELOG.md#2163",
          "enum": [
            "true",
            "false"
          ]
        },
        "ENABLE_PROMPT_CACHING_1H": {
          "type": "string",
          "description": "Request a 1-hour prompt cache TTL instead of the 5-minute default (billed at a higher rate). See https://code.claude.com/docs/en/prompt-caching#cache-lifetime",
          "enum": [
            "0",
            "1"
          ]
        },
        "ENABLE_TOOL_SEARCH": {
          "type": "string",
          "description": "Control MCP tool search: \"true\" always defers and sends the beta header (requests fail on Google Cloud's Agent Platform models earlier than Sonnet 4.5/Opus 4.5 or on proxies that do not support tool_reference); \"auto\" loads tools upfront if they fit within 10% of context; \"auto:N\" sets a custom threshold percentage (e.g. auto:5); \"false\" loads all tools upfront. Also applies when ANTHROPIC_BASE_URL points to a non-first-party host. See https://code.claude.com/docs/en/google-vertex-ai#4-configure-claude-code"
        },
        "FALLBACK_FOR_ALL_PRIMARY_MODELS": {
          "type": "string",
          "description": "Set to any non-empty value to make all models (not only Opus) stop retrying with a repeated-overload error when no fallback model is configured. See https://code.claude.com/docs/en/env-vars"
        },
        "FORCE_AUTOUPDATE_PLUGINS": {
          "type": "string",
          "description": "Keep plugin auto-updates enabled even when DISABLE_AUTOUPDATER=1 is set. See https://code.claude.com/docs/en/discover-plugins#configure-auto-updates",
          "enum": [
            "0",
            "1"
          ]
        },
        "FORCE_HYPERLINK": {
          "type": "string",
          "description": "Set to 1 to enable clickable OSC 8 hyperlinks when your terminal supports them but is not auto-detected, or 0 to disable them",
          "enum": [
            "0",
            "1"
          ]
        },
        "FORCE_PROMPT_CACHING_5M": {
          "type": "string",
          "description": "Force a 5-minute cache TTL regardless of authentication method; overrides ENABLE_PROMPT_CACHING_1H or a managed-settings TTL. See https://code.claude.com/docs/en/prompt-caching#override-the-ttl",
          "enum": [
            "0",
            "1"
          ]
        },
        "GOOGLE_APPLICATION_CREDENTIALS": {
          "type": "string",
          "description": "Path to a GCP credential configuration file (service account key or workload identity federation config) used for Google Cloud's Agent Platform authentication. See https://code.claude.com/docs/en/google-vertex-ai#3-configure-gcp-credentials"
        },
        "HTTPS_PROXY": {
          "type": "string",
          "description": "HTTPS proxy URL (recommended over HTTP_PROXY)"
        },
        "HTTP_PROXY": {
          "type": "string",
          "description": "HTTP proxy URL"
        },
        "IS_DEMO": {
          "type": "string",
          "description": "Set to 1 to enable demo mode: hides email and organization name from the header and /status output and skips onboarding. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "MAX_MCP_OUTPUT_TOKENS": {
          "type": "string",
          "description": "Maximum number of tokens allowed in MCP tool output before truncation (default: 25000). Claude Code displays a warning above 10000 tokens. For tools that declare anthropic/maxResultSizeChars, that character limit replaces this token limit for text content, but image content from those tools is still subject to this limit. See https://code.claude.com/docs/en/mcp"
        },
        "MAX_STRUCTURED_OUTPUT_RETRIES": {
          "type": "string",
          "description": "Number of times to retry when the model's response fails validation against --json-schema in non-interactive (-p) mode (default 5). See https://code.claude.com/docs/en/env-vars"
        },
        "MAX_THINKING_TOKENS": {
          "type": "string",
          "description": "Override the extended thinking token budget; set to 0 to disable thinking on the Anthropic API. On adaptive reasoning models (Opus 4.7+, Opus 4.8, Fable 5) a nonzero budget is ignored unless CLAUDE_CODE_DISABLE_ADAPTIVE_THINKING is set. See https://code.claude.com/docs/en/model-config#extended-thinking"
        },
        "MCP_CLIENT_SECRET": {
          "type": "string",
          "description": "OAuth client secret for MCP servers that require pre-configured credentials (avoids the interactive prompt when adding a server with --client-secret). See https://code.claude.com/docs/en/env-vars"
        },
        "MCP_CONNECTION_NONBLOCKING": {
          "type": "string",
          "description": "Controls whether startup waits for MCP servers to connect before the first query. Non-blocking by default since v2.1.142; set to 0 to restore the blocking 5-second connection wait. See https://code.claude.com/docs/en/env-vars",
          "enum": [
            "0",
            "1"
          ]
        },
        "MCP_CONNECT_TIMEOUT_MS": {
          "type": "string",
          "description": "How long blocking MCP startup waits in milliseconds for the connection batch before snapshotting the tool list (default 5000). Applies when MCP_CONNECTION_NONBLOCKING=0 or for alwaysLoad servers. See https://code.claude.com/docs/en/env-vars"
        },
        "MCP_OAUTH_CALLBACK_PORT": {
          "type": "string",
          "description": "Fixed port for the OAuth redirect callback, as an alternative to --callback-port when adding an MCP server with pre-configured credentials. See https://code.claude.com/docs/en/env-vars"
        },
        "MCP_REMOTE_SERVER_CONNECTION_BATCH_SIZE": {
          "type": "string",
          "description": "Maximum number of remote MCP servers (HTTP/SSE) to connect in parallel during startup (default 20). See https://code.claude.com/docs/en/env-vars"
        },
        "MCP_SERVER_CONNECTION_BATCH_SIZE": {
          "type": "string",
          "description": "Maximum number of local MCP servers (stdio) to connect in parallel during startup (default 3). See https://code.claude.com/docs/en/env-vars"
        },
        "MCP_TIMEOUT": {
          "type": "string",
          "description": "Timeout in milliseconds for MCP server startup (default 30000). See https://code.claude.com/docs/en/env-vars"
        },
        "MCP_TOOL_TIMEOUT": {
          "type": "string",
          "description": "Timeout in milliseconds for MCP tool execution (default: 100000000, about 28 hours). A per-server timeout field in .mcp.json overrides this for that server. Values below 1000 are floored to one second. See https://code.claude.com/docs/en/mcp"
        },
        "NODE_EXTRA_CA_CERTS": {
          "type": "string",
          "description": "Path to custom CA certificate file"
        },
        "NO_PROXY": {
          "type": "string",
          "description": "Domains to bypass proxy (space or comma-separated, or '*' for all)"
        },
        "OTEL_ATTRIBUTE_VALUE_LENGTH_LIMIT": {
          "type": "string",
          "description": "Standard OpenTelemetry SDK limit on attribute value length. Claude Code caps content-bearing telemetry attributes at the smaller of this and CLAUDE_CODE_OTEL_CONTENT_MAX_LENGTH, so the truncation marker stays within the SDK limit. Claude Code reads the OTEL_LOGRECORD_ATTRIBUTE_VALUE_LENGTH_LIMIT and OTEL_SPAN_ATTRIBUTE_VALUE_LENGTH_LIMIT variants the same way, and the smallest set value applies to all signals. Requires Claude Code v2.1.214 or later. See https://code.claude.com/docs/en/monitoring-usage#common-configuration-variables"
        },
        "OTEL_EXPORTER_OTLP_CERTIFICATE": {
          "type": "string",
          "description": "Path to the CA certificate for gRPC OTLP mTLS. See https://code.claude.com/docs/en/monitoring-usage#mtls-authentication"
        },
        "OTEL_EXPORTER_OTLP_CLIENT_CERTIFICATE": {
          "type": "string",
          "description": "Path to the client certificate for gRPC OTLP mTLS. See https://code.claude.com/docs/en/monitoring-usage#mtls-authentication"
        },
        "OTEL_EXPORTER_OTLP_CLIENT_KEY": {
          "type": "string",
          "description": "Path to the client private key for gRPC OTLP mTLS. See https://code.claude.com/docs/en/monitoring-usage#mtls-authentication"
        },
        "OTEL_EXPORTER_OTLP_ENDPOINT": {
          "type": "string",
          "description": "OTLP exporter endpoint for all signals (e.g. http://localhost:4317). See https://code.claude.com/docs/en/monitoring-usage#common-configuration-variables"
        },
        "OTEL_EXPORTER_OTLP_HEADERS": {
          "type": "string",
          "description": "Headers sent with OTLP exporter requests (e.g. Authorization=Bearer token). See https://code.claude.com/docs/en/monitoring-usage#common-configuration-variables"
        },
        "OTEL_EXPORTER_OTLP_LOGS_CLIENT_CERTIFICATE": {
          "type": "string",
          "description": "Path to the client certificate for gRPC OTLP mTLS, overriding OTEL_EXPORTER_OTLP_CLIENT_CERTIFICATE for logs only. See https://code.claude.com/docs/en/monitoring-usage#mtls-authentication"
        },
        "OTEL_EXPORTER_OTLP_LOGS_CLIENT_KEY": {
          "type": "string",
