      "propertyNames": {
        "pattern": "^[A-Z_][A-Z0-9_]*$"
      },
      "additionalProperties": {
        "type": "string",
        "description": "Environment variable value"
      }
    },
    "attribution": {
      "type": "object",
      "description": "Customize attribution for git commits and pull requests. See https://code.claude.com/docs/en/settings#attribution-settings",
      "additionalProperties": false,
      "properties": {
        "commit": {
          "type": "string",
          "description": "Attribution for git commits, including any trailers. Empty string hides commit attribution"
        },
        "pr": {
          "type": "string",
          "description": "Attribution for pull request descriptions. Empty string hides pull request attribution"
        },
        "sessionUrl": {
          "type": "boolean",
          "description": "Whether to append the claude.ai session link as a Claude-Session trailer on commits and a link in pull request descriptions when running from a web or Remote Control session. Defaults to true; set to false to omit the link. See https://code.claude.com/docs/en/settings#attribution-settings",
          "default": true
        }
      }
    },
    "includeGitInstructions": {
      "type": "boolean",
      "description": "Include built-in git commit and PR workflow instructions in Claude's system prompt. Also configurable via CLAUDE_CODE_DISABLE_GIT_INSTRUCTIONS environment variable (set to 1 to disable). See https://code.claude.com/docs/en/settings#available-settings",
      "default": true
    },
    "includeCoAuthoredBy": {
      "type": "boolean",
      "description": "DEPRECATED. Use 'attribution' instead. Whether to include the co-authored-by Claude byline in git commits and pull requests (default: true)",
      "default": true
    },
    "plansDirectory": {
      "type": "string",
      "description": "Customize where plan files are stored. Path is relative to project root (default: ~/.claude/plans)",
      "default": "~/.claude/plans",
      "examples": [
        "./plans"
      ]
    },
    "respectGitignore": {
      "type": "boolean",
      "description": "Control whether the @ file picker respects .gitignore patterns. When true (default), files matching .gitignore patterns are excluded from suggestions",
      "default": true
    },
    "permissions": {
      "type": "object",
      "properties": {
        "allow": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/permissionRule"
          },
          "description": "List of permission rules for allowed operations",
          "uniqueItems": true
        },
        "deny": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/permissionRule"
          },
          "description": "List of permission rules for denied operations",
          "uniqueItems": true
        },
        "ask": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/permissionRule"
          },
          "description": "List of permission rules that should always prompt for confirmation",
          "uniqueItems": true
        },
        "defaultMode": {
          "type": "string",
          "enum": [
            "acceptEdits",
            "bypassPermissions",
            "default",
            "delegate",
            "dontAsk",
            "plan",
            "auto",
            "manual"
          ],
          "description": "Default permission mode.\n\"default\": prompts on first use.\nUNDOCUMENTED. \"manual\": accepted alias for \"default\" (the CLI/VS Code/JetBrains UI now labels this mode \"Manual\" as of v2.1.200; permission-modes.md has not yet been updated to mention it).\n\"acceptEdits\": auto-accepts file edits.\n\"plan\": read-only, no modifications.\nUNDOCUMENTED. \"delegate\": coordination-only for agent team leads (agent teams are experimental; enable via CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS).\n\"dontAsk\": auto-denies unless pre-approved via permissions.\n\"bypassPermissions\": skips all prompts (use only in isolated environments).\n\"auto\": auto-approves tool calls with background safety checks that verify actions align with your request.\nSee https://code.claude.com/docs/en/permissions"
        },
        "disableBypassPermissionsMode": {
          "type": "string",
          "enum": [
            "disable"
          ],
          "description": "Disable the ability to bypass permission prompts"
        },
        "disableAutoMode": {
          "type": "string",
          "enum": [
            "disable"
          ],
          "description": "Set to \"disable\" to prevent auto mode from being activated. Removes `auto` from the Shift+Tab cycle and rejects `--permission-mode auto` at startup. Most useful in managed settings where users cannot override it. See https://code.claude.com/docs/en/permissions"
        },
        "additionalDirectories": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "description": "Additional directories to include in the permission scope",
          "examples": [
            [
              "//Users/alice/Documents",
              "~/projects"
            ]
          ],
          "uniqueItems": true
        }
      },
      "additionalProperties": false,
      "description": "Tool usage permissions configuration.\nSee https://code.claude.com/docs/en/permissions and https://code.claude.com/docs/en/settings#permission-settings\nSee https://code.claude.com/docs/en/tools-reference for full list of tools available to Claude.",
      "examples": [
        {
          "allow": [
            "Bash(git add:*)"
          ],
          "ask": [
            "Bash(gh pr create:*)",
            "Bash(git commit:*)"
          ],
          "deny": [
            "Read(*.env)",
            "Bash(rm:*)",
            "Bash(curl:*)"
          ],
          "defaultMode": "default"
        }
      ]
    },
    "language": {
      "type": "string",
      "description": "Configure Claude's preferred response language (e.g., \"japanese\", \"spanish\", \"french\"). Claude will respond in this language by default. Also sets the voice dictation language and terminal tab session title generation. See https://code.claude.com/docs/en/settings#available-settings",
      "examples": [
        "japanese",
        "spanish",
        "french"
      ]
    },
    "model": {
      "type": "string",
      "description": "Override the default model used by Claude Code. For finer control, use environment variables: ANTHROPIC_MODEL (runtime override), ANTHROPIC_DEFAULT_OPUS_MODEL, ANTHROPIC_DEFAULT_SONNET_MODEL, ANTHROPIC_DEFAULT_HAIKU_MODEL (per-class pinning), CLAUDE_CODE_SUBAGENT_MODEL (subagent model). See https://code.claude.com/docs/en/model-config"
    },
    "availableModels": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Restrict which models users can select. When defined at multiple settings levels (user, project, etc.), arrays are merged and deduplicated. See https://code.claude.com/docs/en/model-config#restrict-model-selection",
      "examples": [
        [
          "sonnet",
          "haiku"
        ]
      ]
    },
    "modelOverrides": {
      "type": "object",
      "additionalProperties": {
        "type": "string"
      },
      "description": "Map Anthropic model IDs to provider-specific model IDs such as Bedrock inference profile ARNs, Vertex AI version names, or Foundry deployment names. Each model picker entry uses its mapped value when calling the provider API. Unknown keys are ignored. See https://code.claude.com/docs/en/model-config#override-model-ids-per-version",
      "examples": [
        {
          "claude-opus-4-6": "arn:aws:bedrock:us-east-2:123456789012:application-inference-profile/opus-prod"
        }
      ]
    },
    "effortLevel": {
      "type": "string",
      "enum": [
        "low",
        "medium",
        "high",
        "xhigh"
      ],
      "description": "Persist adaptive reasoning effort across sessions. Set to low, medium, high, or xhigh; max and ultracode are session-only and are not accepted in the settings file (use the CLAUDE_CODE_EFFORT_LEVEL environment variable or /effort for a session-only max). Effort is supported on Fable 5, Opus 4.8, Opus 4.7, Opus 4.6, and Sonnet 4.6, with xhigh sitting between high and max (added in v2.1.111). Defaults: Fable 5 and Opus 4.8 default to high; Opus 4.6 and Sonnet 4.6 default to high on all plans (Pro/Max raised from medium to high in v2.1.117); Opus 4.7 defaults to xhigh. Use /effort auto to reset to model default. Also configurable via CLAUDE_CODE_EFFORT_LEVEL environment variable. See https://code.claude.com/docs/en/model-config#adjust-effort-level"
    },
    "fastMode": {
      "type": "boolean",
      "description": "Enable fast mode, which uses Claude Opus 5 by default (since v2.1.219) for faster output at higher per-token cost without downgrading to a smaller model. Requires extra usage enabled. Toggle with the /fast command. Supported on Opus 5 and Opus 4.8; fast mode for Opus 4.7 was deprecated on June 25, 2026 and removed on July 24, 2026. Before v2.1.219 fast mode defaulted to Opus 4.8 (v2.1.154 through v2.1.218) and to Opus 4.7 (v2.1.142 through v2.1.153). See https://code.claude.com/docs/en/fast-mode",
      "default": false
    },
    "fastModePerSessionOptIn": {
      "type": "boolean",
      "description": "Require per-session opt-in for fast mode. When true, fast mode does not persist across sessions and users must enable it with /fast each session. Useful for controlling costs. See https://code.claude.com/docs/en/fast-mode",
      "default": false
    },
    "feedbackSurveyRate": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Probability (0–1) that the session quality survey appears when eligible. A value of 0.05 means 5% of eligible sessions. See https://code.claude.com/docs/en/settings#available-settings",
      "examples": [
        0.05
      ]
    },
    "enableAllProjectMcpServers": {
      "type": "boolean",
      "description": "Whether to automatically approve all MCP servers in the project. See https://code.claude.com/docs/en/mcp",
      "examples": [
        true
      ]
    },
    "enabledMcpjsonServers": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "List of approved MCP servers from .mcp.json. See https://code.claude.com/docs/en/mcp",
      "examples": [
        [
          "memory",
          "github"
        ]
      ]
    },
    "disabledMcpjsonServers": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "List of rejected MCP servers from .mcp.json. See https://code.claude.com/docs/en/mcp",
      "examples": [
        [
          "filesystem"
        ]
      ]
    },
    "allowedMcpServers": {
      "type": "array",
      "items": {
        "anyOf": [
          {
            "type": "object",
            "properties": {
              "serverName": {
                "type": "string",
                "pattern": "^[a-zA-Z0-9_-]+$",
                "description": "Name of the MCP server that users are allowed to configure"
              }
            },
            "required": [
              "serverName"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "serverCommand": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Exact command and arguments used to start stdio servers"
              }
            },
            "required": [
              "serverCommand"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "serverUrl": {
                "type": "string",
                "description": "URL pattern for remote servers, supports wildcards (e.g., https://*.example.com/*)"
              }
            },
            "required": [
              "serverUrl"
            ],
            "additionalProperties": false
          }
        ]
      },
      "description": "Enterprise allowlist of MCP servers that can be used. Applies to all scopes including enterprise servers from managed-mcp.json. If undefined, all servers are allowed. If empty array, no servers are allowed. Denylist takes precedence - if a server is on both lists, it is denied. See https://code.claude.com/docs/en/mcp#restriction-options"
    },
    "deniedMcpServers": {
      "type": "array",
      "items": {
        "anyOf": [
          {
            "type": "object",
            "properties": {
              "serverName": {
                "type": "string",
                "pattern": "^[a-zA-Z0-9_-]+$",
                "description": "Name of the MCP server that is explicitly blocked"
              }
            },
            "required": [
              "serverName"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "serverCommand": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Exact command and arguments used to start stdio servers"
              }
            },
            "required": [
              "serverCommand"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "serverUrl": {
                "type": "string",
                "description": "URL pattern for remote servers, supports wildcards (e.g., https://*.example.com/*)"
              }
            },
            "required": [
              "serverUrl"
            ],
            "additionalProperties": false
          }
        ]
      },
      "description": "Enterprise denylist of MCP servers that are explicitly blocked. If a server is on the denylist, it will be blocked across all scopes including enterprise. Denylist takes precedence over allowlist - if a server is on both lists, it is denied. See https://code.claude.com/docs/en/mcp#restriction-options"
    },
    "httpHookAllowedEnvVars": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "Allowlist of environment variable names HTTP hooks may interpolate into headers. When set, each hook's effective allowedEnvVars is the intersection with this list. Undefined = no restriction. Arrays merge across settings sources. See https://code.claude.com/docs/en/settings#hook-configuration",
      "examples": [
        [
          "MY_TOKEN",
          "HOOK_SECRET"
        ]
      ]
    },
    "hooks": {
      "type": "object",
      "additionalProperties": false,
      "description": "Lifecycle event hooks that run at configurable points during Claude Code operation (tool use, session start/end, notifications, prompt submit, message display, and more), not just before/after tool executions. See https://code.claude.com/docs/en/hooks",
      "examples": [
        {
          "PostToolUse": [
            {
              "matcher": "Edit|Write",
              "hooks": [
                {
                  "type": "command",
                  "command": "prettier --write",
                  "timeout": 5
                }
              ]
            }
          ]
        }
      ],
      "properties": {
        "PreToolUse": {
          "type": "array",
          "description": "Hooks that run before tool calls",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PostToolUse": {
          "type": "array",
          "description": "Hooks that run after tool completion",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PostToolUseFailure": {
          "type": "array",
          "description": "Hooks that run after a tool fails",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PermissionRequest": {
          "type": "array",
          "description": "Hooks that run when a permission dialog appears",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "Notification": {
          "type": "array",
          "description": "Hooks that trigger on notifications",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "UserPromptSubmit": {
          "type": "array",
          "description": "Hooks that run when a user submits a prompt",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "Stop": {
          "type": "array",
          "description": "Hooks that run when agents finish responding. Does not run on user interrupt",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "StopFailure": {
          "type": "array",
          "description": "Hooks that run when a turn ends due to an API error (e.g., rate_limit, authentication_failed, billing_error, invalid_request, server_error, max_output_tokens, unknown). Matcher can scope to specific error types. Hook output and exit code are ignored. See https://code.claude.com/docs/en/hooks",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "SubagentStart": {
          "type": "array",
          "description": "Hooks that run when a subagent is spawned",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "SubagentStop": {
          "type": "array",
          "description": "Hooks that run when subagents finish responding",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PreCompact": {
          "type": "array",
          "description": "Hooks that run before the context is compacted",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PostCompact": {
          "type": "array",
          "description": "Hooks that run after the context is compacted. See https://code.claude.com/docs/en/hooks",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "Elicitation": {
          "type": "array",
          "description": "Hooks that run when an MCP server requests user input during a tool call. See https://code.claude.com/docs/en/hooks",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "ElicitationResult": {
          "type": "array",
          "description": "Hooks that run after a user responds to an MCP elicitation, before the response is sent back to the server. See https://code.claude.com/docs/en/hooks",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "TeammateIdle": {
          "type": "array",
          "description": "Hooks that run when an agent team teammate is about to go idle. Exit code 2 sends feedback and keeps the teammate working. Does not support matchers. Agent teams are experimental. See https://code.claude.com/docs/en/hooks#teammateidle",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "TaskCompleted": {
          "type": "array",
          "description": "Hooks that run when a task is being marked as completed. Exit code 2 prevents completion and sends feedback. Does not support matchers. See https://code.claude.com/docs/en/hooks#taskcompleted",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "Setup": {
          "type": "array",
          "description": "UNDOCUMENTED. Hooks that run during repository initialization (--init, --init-only) or maintenance (--maintenance)",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "InstructionsLoaded": {
          "type": "array",
          "description": "Hooks that run when a CLAUDE.md or .claude/rules/*.md file is loaded into context. Fires at session start and when files are lazily loaded (e.g., nested traversal, path glob match). No decision control; used for audit logging and observability. Does not support matchers. See https://code.claude.com/docs/en/hooks#instructionsloaded",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "CwdChanged": {
          "type": "array",
          "description": "Hooks that run when the working directory changes. Provides cwd (new directory) and previous_cwd. Matchers are ignored; fires on every directory change. See https://code.claude.com/docs/en/hooks#cwdchanged",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "FileChanged": {
          "type": "array",
          "description": "Hooks that run when a watched file is created, modified, or deleted. Supports filename matchers. Provides file_path and file_event_type (created, modified, deleted). See https://code.claude.com/docs/en/hooks#filechanged",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "ConfigChange": {
          "type": "array",
          "description": "Hooks that run when settings, managed settings, or skill files change during a session. Supports matchers: user_settings, project_settings, local_settings, policy_settings, skills. Command handlers only. Exit code 2 blocks the change (except policy_settings which is audit-only). See https://code.claude.com/docs/en/hooks#configchange",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "WorktreeCreate": {
          "type": "array",
          "description": "Hooks that run when a worktree is created via --worktree or isolation: \"worktree\" in subagents. Command handlers only, no matchers. Hook must print absolute path to created worktree on stdout; non-zero exit fails creation. See https://code.claude.com/docs/en/hooks#worktreecreate",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "WorktreeRemove": {
          "type": "array",
          "description": "Hooks that run when a worktree is being removed at session exit or when a subagent finishes. Command handlers only, no matchers. Used for cleanup tasks; cannot block removal. See https://code.claude.com/docs/en/hooks#worktreeremove",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "SessionStart": {
          "type": "array",
          "description": "Hooks that run when a new session starts",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "SessionEnd": {
          "type": "array",
          "description": "Hooks that run when a session ends",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PostToolBatch": {
          "type": "array",
          "description": "Hooks that run after a full batch of parallel tool calls resolves, before the next model call. Exit code 2 blocks the agentic loop. Does not support matchers. See https://code.claude.com/docs/en/hooks",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "TaskCreated": {
          "type": "array",
          "description": "Hooks that run when a task is being created via TaskCreate. Exit code 2 rolls back task creation. Does not support matchers. See https://code.claude.com/docs/en/hooks#taskcreated",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "PermissionDenied": {
          "type": "array",
          "description": "Hooks that run when a tool call is denied by the auto mode classifier. Supports matchers on tool name. See https://code.claude.com/docs/en/hooks",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "UserPromptExpansion": {
          "type": "array",
          "description": "Hooks that run when a user-typed command expands into a prompt, before it reaches Claude. Exit code 2 blocks the expansion. Supports matchers on command name. See https://code.claude.com/docs/en/hooks",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "MessageDisplay": {
          "type": "array",
          "description": "Hooks that run while assistant message text is displayed",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        },
        "DirectoryAdded": {
          "type": "array",
          "description": "UNDOCUMENTED. Hooks that run after /add-dir or the SDK register_repo_root control request registers a new working directory mid-session (added v2.1.219)",
          "items": {
            "$ref": "#/$defs/hookMatcher"
          }
        }
      }
    },
    "disableAllHooks": {
      "type": "boolean",
      "description": "Disable all hooks and statusLine execution. When true in managed settings, user and project-level disableAllHooks cannot override it. See https://code.claude.com/docs/en/hooks#disable-or-remove-hooks"
    },
    "allowedChannelPlugins": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "marketplace": {
            "type": "string",
            "description": "Name of the marketplace the channel plugin is installed from"
          },
          "plugin": {
            "type": "string",
            "description": "Name of the channel plugin allowed to run"
          }
        },
        "required": [
          "marketplace",
          "plugin"
        ]
      },
      "description": "(Managed settings only) Allowlist of channel plugins that may run, each identified by its marketplace and plugin name. When set, only the listed plugins can push inbound channel messages while channelsEnabled is true. Replaces the default Anthropic allowlist when set; undefined falls back to the default and an empty array blocks all channel plugins. Requires channelsEnabled: true. See https://code.claude.com/docs/en/channels#restrict-which-channel-plugins-can-run"
    },
    "allowedHttpHookUrls": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "Allowlist of URL patterns that HTTP hooks may target. Supports * as a wildcard. When set, hooks with non-matching URLs are blocked. Undefined = no restriction, empty array = block all HTTP hooks. Arrays merge across settings sources. See https://code.claude.com/docs/en/settings#hook-configuration",
      "examples": [
        [
          "https://hooks.example.com/*",
          "http://localhost:*"
        ]
      ]
    },
    "allowManagedHooksOnly": {
      "type": "boolean",
      "description": "(Managed settings only) Prevent loading of user, project, and plugin hooks. Only allows managed hooks and SDK hooks. See https://code.claude.com/docs/en/settings#hook-configuration"
    },
    "allowManagedPermissionRulesOnly": {
      "type": "boolean",
      "description": "(Managed settings only) Prevent user and project settings from defining allow, ask, or deny permission rules. Only rules in managed settings apply. See https://code.claude.com/docs/en/settings#permission-settings"
    },
    "statusLine": {
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "description": "The type of status line handler; must be set to \"command\" to run a custom shell script that receives JSON session data via stdin.",
          "const": "command"
        },
        "command": {
          "type": "string",
          "description": "A shell command or path to a script that displays session information (context usage, costs, git status, etc.) by reading JSON data from stdin and writing output to stdout. See https://code.claude.com/docs/en/statusline"
        },
        "padding": {
          "type": "number",
          "description": "Optional number of extra horizontal spacing characters added to the status line content; defaults to 0."
        },
        "refreshInterval": {
          "type": "integer",
          "minimum": 1,
          "description": "Re-run the status line command every N seconds in addition to event-driven updates. Leave unset to run only on events. Useful for time-based data like clocks, or when background subagents change git state while the main session is idle. See https://code.claude.com/docs/en/statusline"
        },
        "hideVimModeIndicator": {
          "type": "boolean",
