    "skippedMarketplaces": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "List of marketplace names the user has chosen not to install when prompted. See https://code.claude.com/docs/en/discover-plugins"
    },
    "skippedPlugins": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "List of plugin IDs (plugin@marketplace format) the user has chosen not to install when prompted. See https://code.claude.com/docs/en/discover-plugins"
    },
    "forceLoginMethod": {
      "type": "string",
      "enum": [
        "claudeai",
        "console",
        "gateway"
      ],
      "description": "Use \"claudeai\" to restrict login to Claude.ai accounts, \"console\" to restrict login to Claude Console accounts, or \"gateway\" to restrict login to a cloud gateway. On Claude Code v2.1.212 or later, every first-party login path enforces the restriction, including the VS Code extension, the Agent SDK, `claude setup-token`, and /install-github-app; before v2.1.212, only terminal logins enforced it. See https://code.claude.com/docs/en/authentication#restrict-login-to-your-organization",
      "examples": [
        "claudeai"
      ]
    },
    "forceLoginOrgUUID": {
      "oneOf": [
        {
          "type": "string",
          "minLength": 1
        },
        {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      ],
      "description": "Organization UUID to use for OAuth login, or an array of UUIDs to allow several organizations. An empty array fails closed and blocks every login. See https://code.claude.com/docs/en/authentication#restrict-login-to-your-organization",
      "examples": [
        "xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
      ]
    },
    "otelHeadersHelper": {
      "type": "string",
      "description": "Path to an executable, or a shell command line with arguments, that outputs OpenTelemetry headers as a JSON object. Runs at startup and re-runs on the interval set by CLAUDE_CODE_OTEL_HEADERS_HELPER_DEBOUNCE_MS. Requires CLAUDE_CODE_ENABLE_TELEMETRY=1. See https://code.claude.com/docs/en/monitoring-usage#dynamic-headers",
      "minLength": 1
    },
    "outputStyle": {
      "type": "string",
      "description": "Controls the output style for assistant responses. Built-in styles: default, Proactive, Explanatory, Learning. Custom styles can be added in ~/.claude/output-styles/ or .claude/output-styles/. See https://code.claude.com/docs/en/output-styles",
      "examples": [
        "default",
        "Proactive",
        "Explanatory",
        "Learning"
      ],
      "minLength": 1
    },
    "skipWebFetchPreflight": {
      "type": "boolean",
      "description": "Skip the WebFetch blocklist check for enterprise environments with restrictive security policies. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "sandbox": {
      "type": "object",
      "description": "Sandbox execution configuration. See https://code.claude.com/docs/en/sandboxing",
      "properties": {
        "network": {
          "type": "object",
          "description": "Configures network isolation settings for the sandboxed bash environment, including domain restrictions, Unix socket access, and custom proxy configuration.",
          "properties": {
            "allowUnixSockets": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Allow Unix domain sockets for local IPC (SSH agent, Docker, etc.). Provide an array of specific paths. Defaults to blocking if not specified. See https://code.claude.com/docs/en/sandboxing#network-isolation"
            },
            "allowLocalBinding": {
              "type": "boolean",
              "description": "Allow binding to local network addresses (e.g., localhost ports). Defaults to false if not specified. See https://code.claude.com/docs/en/sandboxing#network-isolation"
            },
            "httpProxyPort": {
              "type": "integer",
              "minimum": 1,
              "maximum": 65535,
              "description": "HTTP proxy port to use for network filtering. If not specified, a proxy server will be started automatically. See https://code.claude.com/docs/en/sandboxing#custom-proxy-configuration"
            },
            "socksProxyPort": {
              "type": "integer",
              "minimum": 1,
              "maximum": 65535,
              "description": "SOCKS proxy port to use for network filtering. If not specified, a proxy server will be started automatically. See https://code.claude.com/docs/en/sandboxing#custom-proxy-configuration"
            },
            "allowAllUnixSockets": {
              "type": "boolean",
              "description": "Allow all Unix domain socket connections. If true, this overrides allowUnixSockets. See https://code.claude.com/docs/en/sandboxing#network-isolation"
            },
            "allowedDomains": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              },
              "description": "Allowlist of network domains for sandboxed commands. Supports wildcard patterns like *.example.com. See https://code.claude.com/docs/en/sandboxing#network-isolation"
            },
            "deniedDomains": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              },
              "description": "Blocklist of network domains for sandboxed commands. Blocks specific domains even when a broader allowedDomains wildcard would otherwise permit them. Supports wildcard patterns like *.example.com. See https://code.claude.com/docs/en/sandboxing#network-isolation"
            },
            "allowManagedDomainsOnly": {
              "type": "boolean",
              "description": "(Managed settings only) Only allowedDomains and WebFetch(domain:...) allow rules from managed settings are respected. User, project, local, and flag settings domains are ignored. Denied domains are still respected from all sources. Non-allowed domains are automatically blocked without user prompts. See https://code.claude.com/docs/en/sandboxing#network-isolation"
            },
            "allowMachLookup": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              },
              "description": "macOS only. Additional XPC/Mach service names the sandbox may look up. Supports a single trailing * for prefix matching. Needed for tools that communicate via XPC such as the iOS Simulator or Playwright. See https://code.claude.com/docs/en/sandboxing#network-isolation",
              "examples": [
                [
                  "com.apple.coresimulator.*"
                ]
              ]
            },
            "tlsTerminate": {
              "type": "object",
              "description": "Experimental. Terminate TLS inside the sandbox proxy so it can read the contents of HTTPS requests. Required for mask credential substitution. Set {} to generate an ephemeral certificate authority for the session, or set caCertPath and caKeyPath to use your own. Only honored from user, managed, or CLI --settings settings, not from .claude/settings.json or .claude/settings.local.json. Requires Claude Code v2.1.199 or later. See https://code.claude.com/docs/en/sandboxing#protect-credentials",
              "properties": {
                "caCertPath": {
                  "type": "string",
                  "description": "Path to your own certificate authority certificate"
                },
                "caKeyPath": {
                  "type": "string",
                  "description": "Path to your own certificate authority private key"
                }
              },
              "additionalProperties": false
            },
            "strictAllowlist": {
              "type": "boolean",
              "description": "UNDOCUMENTED. Deny non-allowlisted hosts for sandboxed commands without prompting (added v2.1.219). See https://code.claude.com/docs/en/sandboxing#network-isolation"
            }
          },
          "additionalProperties": false
        },
        "ignoreViolations": {
          "type": "object",
          "additionalProperties": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "List of filesystem paths to ignore sandbox violations for when this command pattern matches"
          },
          "description": "Map of command patterns to filesystem paths to ignore violations for. Use \"*\" to match all commands"
        },
        "excludedCommands": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Commands that should never run in the sandbox (e.g., [\"git\", \"docker\"]). See https://code.claude.com/docs/en/sandboxing#configure-sandboxing"
        },
        "autoAllowBashIfSandboxed": {
          "type": "boolean",
          "description": "Automatically allow bash commands without prompting when they run in the sandbox. Only applies to commands that will run sandboxed. See https://code.claude.com/docs/en/sandboxing#sandbox-modes",
          "default": true
        },
        "enableWeakerNetworkIsolation": {
          "type": "boolean",
          "description": "macOS only. Allow access to the system TLS trust service (com.apple.trustd.agent) in the sandbox. Required for Go-based tools like gh, gcloud, and terraform to verify TLS certificates when using httpProxyPort with a MITM proxy and custom CA. Reduces security by opening a potential data exfiltration path. Default: false. See https://code.claude.com/docs/en/sandboxing",
          "default": false
        },
        "enableWeakerNestedSandbox": {
          "type": "boolean",
          "description": "Enable weaker sandbox mode for unprivileged docker environments where --proc mounting fails. This significantly reduces the strength of the sandbox and should only be used when this risk is acceptable. Default: false (secure). See https://code.claude.com/docs/en/sandboxing#limitations"
        },
        "allowUnsandboxedCommands": {
          "type": "boolean",
          "description": "Allow commands to run outside the sandbox via the dangerouslyDisableSandbox parameter. When false, the dangerouslyDisableSandbox parameter is completely ignored and all commands must run sandboxed. Default: true. See https://code.claude.com/docs/en/sandboxing#limitations"
        },
        "enabled": {
          "type": "boolean",
          "description": "Enable sandboxed bash. See https://code.claude.com/docs/en/sandboxing#enable-sandboxing"
        },
        "filesystem": {
          "type": "object",
          "description": "Filesystem access control for sandboxed commands. See https://code.claude.com/docs/en/sandboxing#filesystem-isolation",
          "properties": {
            "allowWrite": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              },
              "description": "Paths where subprocesses are allowed to write. Supports prefixes: // (absolute), ~/ (home directory), / (relative to settings file), ./ or no prefix (relative path). See https://code.claude.com/docs/en/sandboxing#granting-subprocess-write-access-to-specific-paths"
            },
            "denyWrite": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              },
              "description": "Paths where subprocesses are explicitly denied write access. Takes precedence over allowWrite. See https://code.claude.com/docs/en/sandboxing#filesystem-isolation"
            },
            "denyRead": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              },
              "description": "Paths where subprocesses are explicitly denied read access. See https://code.claude.com/docs/en/sandboxing#filesystem-isolation"
            },
            "allowRead": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              },
              "description": "Paths to re-allow reading within denyRead regions. Takes precedence over denyRead for matching paths. See https://code.claude.com/docs/en/sandboxing#granting-subprocess-write-access-to-specific-paths"
            },
            "allowManagedReadPathsOnly": {
              "type": "boolean",
              "description": "(Managed settings only) When true, only allowRead paths from managed settings are used; user, project, and local allowRead entries are ignored. denyRead still merges from all sources. See https://code.claude.com/docs/en/sandboxing#filesystem-isolation"
            },
            "disabled": {
              "type": "boolean",
              "description": "Skip filesystem isolation while keeping network isolation: sandboxed commands get unrestricted read and write access to the host filesystem, and network egress stays confined to network.allowedDomains. Only honored from user, managed, or CLI --settings settings (default: false). Requires Claude Code v2.1.216 or later. See https://code.claude.com/docs/en/sandboxing#disable-filesystem-isolation",
              "default": false
            }
          },
          "additionalProperties": false
        },
        "ripgrep": {
          "type": "object",
          "description": "Custom ripgrep configuration for Claude Code's bundled ripgrep support. Overrides the bundled binary and arguments.",
          "additionalProperties": false,
          "required": [
            "command"
          ],
          "properties": {
            "command": {
              "type": "string",
              "description": "Path to the ripgrep binary to use",
              "minLength": 1
            },
            "args": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Additional arguments to pass to the ripgrep binary"
            }
          }
        },
        "bwrapPath": {
          "type": "string",
          "minLength": 1,
          "description": "(Managed setting only) Path to custom bubblewrap (bwrap) binary for Linux/WSL sandbox. Overrides default. See https://code.claude.com/docs/en/server-managed-settings"
        },
        "socatPath": {
          "type": "string",
          "minLength": 1,
          "description": "(Managed setting only) Path to custom socat binary for Linux/WSL network proxying. Overrides default. See https://code.claude.com/docs/en/server-managed-settings"
        },
        "failIfUnavailable": {
          "type": "boolean",
          "description": "When true, make sandbox startup a hard failure if required sandbox dependencies are missing. Default: false (sandbox is skipped with a warning). See https://code.claude.com/docs/en/sandboxing#enable-sandboxing"
        },
        "enabledPlatforms": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "macos",
              "linux",
              "wsl",
              "windows"
            ]
          },
          "description": "Limit the entire sandbox configuration to the listed platforms. On platforms not in the list the sandbox config is inert: no sandbox, no auto-allow, no startup warning, and no failIfUnavailable exit. When omitted, all supported platforms are included. Only honored from managed (policy) settings."
        },
        "credentials": {
          "type": "object",
          "additionalProperties": false,
          "description": "Block sandboxed commands from reading credential files and secret environment variables (v2.1.187+). Entries merge across settings scopes. See https://code.claude.com/docs/en/sandboxing#protect-credentials",
          "properties": {
            "files": {
              "type": "array",
              "description": "Credential file paths to hide from sandboxed commands",
              "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "path": {
                    "type": "string",
                    "description": "Path to the credential file to deny"
                  },
                  "mode": {
                    "type": "string",
                    "enum": [
                      "deny"
                    ],
                    "description": "Access mode; only \"deny\" is supported"
                  }
                },
                "required": [
                  "path",
                  "mode"
                ]
              }
            },
            "envVars": {
              "type": "array",
              "description": "Secret environment variable names to unset for sandboxed commands",
              "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "name": {
                    "type": "string",
                    "description": "Environment variable name to deny"
                  },
                  "mode": {
                    "type": "string",
                    "enum": [
                      "deny"
                    ],
                    "description": "Access mode; only \"deny\" is supported"
                  }
                },
                "required": [
                  "name",
                  "mode"
                ]
              }
            },
            "allowPlaintextInject": {
              "type": "boolean",
              "description": "Allow mask substitution on plain HTTP requests as well as TLS-terminated HTTPS. On plain HTTP the upstream identity is unverified and the credential travels in cleartext, so leave this off outside trusted test networks. Only honored from user, managed, or CLI --settings settings, not from .claude/settings.json or .claude/settings.local.json (default: false). Requires Claude Code v2.1.199 or later. See https://code.claude.com/docs/en/sandboxing#protect-credentials",
              "default": false
            }
          }
        },
        "allowAppleEvents": {
          "type": "boolean",
          "description": "Allow sandboxed commands to send Apple Events on macOS (v2.1.181+). Honored only from user, managed, or CLI settings; project settings cannot enable it. See https://code.claude.com/docs/en/sandboxing#limitations"
        }
      },
      "additionalProperties": false
    },
    "spinnerVerbs": {
      "type": "object",
      "description": "Customize the verbs shown in spinner progress messages",
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "append",
            "replace"
          ],
          "description": "How to combine custom verbs with default spinner verbs: 'append' adds custom verbs to the default list, 'replace' uses only custom verbs"
        },
        "verbs": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "minItems": 1,
          "description": "Custom verbs used in spinner progress text"
        }
      },
      "required": [
        "verbs"
      ],
      "additionalProperties": false
    },
    "spinnerTipsEnabled": {
      "type": "boolean",
      "description": "Show tips in the spinner while Claude is working. Set to false to disable tips (default: true)",
      "default": true
    },
    "spinnerTipsOverride": {
      "type": "object",
      "description": "Customize the tips displayed in the spinner while Claude is working. See https://code.claude.com/docs/en/settings#available-settings",
      "properties": {
        "excludeDefault": {
          "type": "boolean",
          "description": "If true, only show custom tips. If false or absent, custom tips merge with built-in tips",
          "default": false
        },
        "tips": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "description": "Custom tip strings to display in the spinner",
          "minItems": 1
        }
      },
      "required": [
        "tips"
      ],
      "additionalProperties": false
    },
    "terminalProgressBarEnabled": {
      "type": "boolean",
      "description": "Enable the terminal progress bar that shows progress in supported terminals like Windows Terminal and iTerm2 (default: true)",
      "default": true
    },
    "showTurnDuration": {
      "type": "boolean",
      "description": "Show turn duration messages after responses (e.g., \"Cooked for 1m 6s\"). Set to false to hide these messages (default: true)",
      "default": true
    },
    "skillOverrides": {
      "type": "object",
      "additionalProperties": {
        "type": "string",
        "enum": [
          "on",
          "name-only",
          "user-invocable-only",
          "off"
        ]
      },
      "description": "Per-skill visibility overrides. Controls whether skills appear to Claude and in the / picker. Values: 'on' (name and description shown, default), 'name-only' (name only), 'user-invocable-only' (hidden from Claude, visible in /), 'off' (hidden everywhere). Plugin skills are not affected by this setting. See https://code.claude.com/docs/en/skills#override-skill-visibility-from-settings",
      "examples": [
        {
          "legacy-context": "name-only",
          "deploy": "off"
        }
      ]
    },
    "prefersReducedMotion": {
      "type": "boolean",
      "description": "Reduce or disable UI animations (spinners, shimmer, flash effects) for accessibility",
      "default": false
    },
    "prUrlTemplate": {
      "type": "string",
      "description": "URL template for the PR badge shown in the footer and in tool-result summaries. Substitutes placeholders {host}, {owner}, {repo}, {number}, {url} from the gh-reported PR URL. Use this to point PR links at an internal code-review tool instead of github.com. Does not affect #123 autolinks in Claude's prose. See https://code.claude.com/docs/en/settings#available-settings",
      "examples": [
        "https://reviews.example.com/{owner}/{repo}/pull/{number}"
      ]
    },
    "alwaysThinkingEnabled": {
      "type": "boolean",
      "description": "Enable extended thinking by default for all sessions. Typically configured via the /config command rather than editing directly. See https://code.claude.com/docs/en/common-workflows#use-extended-thinking-thinking-mode"
    },
    "companyAnnouncements": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "Company announcements to display at startup (one will be randomly selected if multiple are provided)"
    },
    "teammateMode": {
      "type": "string",
      "enum": [
        "auto",
        "in-process",
        "tmux",
        "iterm2"
      ],
      "description": "How agent team teammates display: \"auto\" picks split panes in tmux or iTerm2, in-process otherwise; \"iterm2\" (added in v2.1.186) forces iTerm2 native split panes and requires the it2 CLI (it shows an error with the install command if it2 is missing). The default is \"in-process\" (it was \"auto\" before v2.1.179). Agent teams are experimental and disabled by default. Enable them by adding CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS to your settings.json or environment. See https://code.claude.com/docs/en/agent-teams#choose-a-display-mode",
      "default": "in-process"
    },
    "worktree": {
      "type": "object",
      "additionalProperties": false,
      "description": "Configuration for --worktree sessions. See https://code.claude.com/docs/en/settings#worktree-settings",
      "properties": {
        "sparsePaths": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "description": "Directories to check out in each worktree via git sparse-checkout (cone mode). Only the listed paths are written to disk, which is faster in large monorepos. See https://code.claude.com/docs/en/settings#worktree-settings",
          "examples": [
            [
              "packages/my-app",
              "shared/utils"
            ]
          ]
        },
        "baseRef": {
          "type": "string",
          "enum": [
            "fresh",
            "head"
          ],
          "default": "fresh",
          "description": "Whether to branch worktrees from origin/<default> (fresh) or local HEAD (head). Default: fresh. Set to 'head' to preserve unpushed commits in new worktrees. See https://code.claude.com/docs/en/settings#worktree-settings"
        },
        "bgIsolation": {
          "type": "string",
          "enum": [
            "worktree",
            "none"
          ],
          "default": "worktree",
          "description": "Isolation mode for background sessions. \"worktree\" blocks Edit/Write in main checkout until EnterWorktree is called; \"none\" lets background jobs edit the working copy directly without EnterWorktree, for repos where worktrees are impractical. See https://code.claude.com/docs/en/settings#worktree-settings"
        },
        "symlinkDirectories": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Directories to symlink from the main repository into each worktree to avoid duplicating large directories on disk. No directories are symlinked by default. See https://code.claude.com/docs/en/settings#worktree-settings",
          "examples": [
            [
              "node_modules",
              ".cache"
            ]
          ]
        }
      }
    },
    "parentSettingsBehavior": {
      "type": "string",
      "enum": [
        "first-wins",
        "merge"
      ],
      "default": "first-wins",
      "description": "(Admin/managed settings only) Controls how SDK managedSettings (parent tier) merge with inherited settings. 'first-wins': first non-empty value applies (default). 'merge': merge arrays and objects. See https://code.claude.com/docs/en/server-managed-settings"
    },
    "pluginTrustMessage": {
      "type": "string",
      "description": "(Managed settings only) Custom message appended to the plugin trust warning shown before installation. Use to provide organization-specific context about approved plugins. See https://code.claude.com/docs/en/settings#plugin-settings",
      "minLength": 1
    },
    "pluginConfigs": {
      "type": "object",
      "additionalProperties": {
        "type": "object",
        "properties": {
          "mcpServers": {
            "type": "object",
            "additionalProperties": {
              "type": "object",
              "additionalProperties": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "number"
                  },
                  {
                    "type": "boolean"
                  },
                  {
                    "type": "array",
                    "items": {
                      "type": "string"
                    }
                  }
                ]
              }
            },
            "description": "User configuration values for MCP servers keyed by server name"
          },
          "options": {
            "type": "object",
            "description": "Non-sensitive option values from the plugin manifest's userConfig, keyed by option name. Sensitive values go to secure storage instead. See https://code.claude.com/docs/en/plugins-reference",
            "additionalProperties": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "number"
                },
                {
                  "type": "boolean"
                },
                {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              ]
            }
          }
        },
        "additionalProperties": false
      },
      "description": "Per-plugin configuration including MCP server user configs and plugin options, keyed by plugin ID (plugin@marketplace format). See https://code.claude.com/docs/en/plugins"
    },
    "allowManagedMcpServersOnly": {
      "type": "boolean",
      "description": "(Managed settings only) When true, only allowedMcpServers from managed settings are respected; MCP servers defined in user, project, or local settings are ignored. deniedMcpServers still merges from all sources. See https://code.claude.com/docs/en/managed-mcp"
    },
    "blockedMarketplaces": {
      "type": "array",
      "description": "(Managed settings only) Blocklist of marketplace sources. These exact sources are blocked from being added as marketplaces. The check happens before downloading, so blocked sources never touch the filesystem.",
      "items": {
        "anyOf": [
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "source": {
                "type": "string",
                "const": "url",
                "description": "Block marketplace fetched from direct URL"
              },
              "url": {
                "type": "string",
                "format": "uri",
                "description": "Direct URL to marketplace.json file"
              },
              "headers": {
                "type": "object",
                "additionalProperties": {
                  "type": "string"
                },
                "description": "Custom HTTP headers (e.g., for authentication)"
              }
            },
            "required": [
              "source",
              "url"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "source": {
                "type": "string",
                "const": "github",
                "description": "Block marketplace from GitHub repository"
              },
              "repo": {
                "type": "string",
                "description": "GitHub repository in owner/repo format"
              },
              "ref": {
                "type": "string",
                "description": "Git branch or tag to use"
              },
              "path": {
                "type": "string",
                "description": "Path to marketplace.json within repo"
              }
            },
            "required": [
              "source",
              "repo"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "source": {
                "type": "string",
                "const": "git",
                "description": "Block marketplace from git repository URL"
              },
              "url": {
                "type": "string",
                "pattern": ".*\\.git$",
                "description": "Full git repository URL"
              },
              "ref": {
                "type": "string",
                "description": "Git branch or tag to use"
              },
              "path": {
                "type": "string",
                "description": "Path to marketplace.json within repo"
              }
            },
            "required": [
              "source",
              "url"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "source": {
                "type": "string",
                "const": "npm",
                "description": "Block marketplace from NPM package"
              },
              "package": {
                "type": "string",
                "description": "NPM package containing marketplace.json"
              }
            },
            "required": [
              "source",
              "package"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "source": {
                "type": "string",
                "const": "file",
                "description": "Block marketplace from local file"
              },
              "path": {
                "type": "string",
                "description": "Local file path to marketplace.json"
              }
            },
            "required": [
              "source",
              "path"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "source": {
                "type": "string",
                "const": "directory",
                "description": "Block marketplace from local directory"
              },
              "path": {
                "type": "string",
                "description": "Local directory containing .claude-plugin/marketplace.json"
              }
            },
            "required": [
              "source",
              "path"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "source": {
                "type": "string",
                "const": "hostPattern",
                "description": "Block marketplace by host pattern matching"
              },
              "hostPattern": {
                "type": "string",
                "description": "Regex pattern to match the host/domain extracted from any marketplace source type"
              }
            },
            "required": [
              "source",
              "hostPattern"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "source": {
                "type": "string",
                "const": "pathPattern",
                "description": "Block marketplace by file/directory path pattern matching"
              },
              "pathPattern": {
                "type": "string",
                "description": "Regex pattern to match file or directory paths for marketplace sources"
              }
            },
            "required": [
              "source",
              "pathPattern"
            ]
          }
        ]
      }
    },
    "agent": {
      "type": "string",
      "description": "Name of an agent (built-in or custom) to use for the main thread. Applies the agent's system prompt, tool restrictions, and model. See https://code.claude.com/docs/en/sub-agents",
      "minLength": 1
    },
    "autoMemoryDirectory": {
      "type": "string",
      "description": "Custom directory path for auto-memory storage. Supports ~/ prefix for home-directory expansion. Ignored if set in checked-in project settings (.claude/settings.json) for security. Defaults to ~/.claude/projects/<sanitized-cwd>/memory/ when unset. See https://code.claude.com/docs/en/memory",
      "minLength": 1
    },
    "autoMode": {
      "type": "object",
      "description": "Customization for the auto mode classifier prompt. Typically configured in managed settings to tune the allow/deny rules used when permissions.defaultMode is \"auto\". By default, allow, soft_deny, and environment REPLACE the corresponding built-in classifier section entirely. Include the literal string \"$defaults\" as an array entry (added in v2.1.118) to splice the built-in defaults in at that position alongside your custom rules. See https://code.claude.com/docs/en/permissions",
      "additionalProperties": false,
      "properties": {
        "allow": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Rules for the auto mode classifier allow section. Replaces the built-in allow rules entirely unless the literal string \"$defaults\" is included as an entry, which splices the built-in defaults in at that position."
        },
        "soft_deny": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Rules for the auto mode classifier soft-deny section. Replaces the built-in soft-deny rules entirely unless the literal string \"$defaults\" is included as an entry, which splices the built-in defaults in at that position."
        },
        "environment": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Entries for the auto mode classifier environment section. Replaces the built-in environment context entirely unless the literal string \"$defaults\" is included as an entry, which splices the built-in defaults in at that position."
        },
        "hard_deny": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Rules for the auto mode classifier hard-deny section. Hard-deny rules block unconditionally regardless of user intent. Replaces the built-in hard-deny rules entirely unless the literal string \"$defaults\" is included as an entry, which splices the built-in defaults in at that position. See https://code.claude.com/docs/en/permissions"
        },
        "classifyAllShell": {
          "type": "boolean",
          "description": "UNDOCUMENTED. Route all Bash/PowerShell commands through the auto mode classifier instead of only arbitrary-code-execution patterns (added in v2.1.193).",
          "default": false
        }
      }
    },
    "channelsEnabled": {
      "type": "boolean",
      "description": "(Managed settings only) Allow channels for the organization. On claude.ai Team and Enterprise plans, channels are blocked when this is unset or false. For Anthropic Console accounts using API key authentication, channels are allowed by default unless the organization deploys managed settings, in which case this key must be set to true. See https://code.claude.com/docs/en/channels#enterprise-controls"
    },
    "defaultShell": {
      "type": "string",
      "enum": [
        "bash",
        "powershell"
      ],
      "description": "Default shell for input-box ! commands. Default: bash. Using \"powershell\" routes ! commands through PowerShell on Windows and requires CLAUDE_CODE_USE_POWERSHELL_TOOL=1 with pwsh on PATH. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "disableDeepLinkRegistration": {
      "type": "string",
      "enum": [
        "disable"
      ],
      "description": "Set to \"disable\" to prevent Claude Code from registering the `claude-cli://` deep-link protocol handler on startup. Most useful in managed settings where users cannot override it. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "disableSkillShellExecution": {
      "type": "boolean",
      "description": "Disable inline shell execution for `` !`...` `` and ` ```! ` blocks in skills and custom slash commands from user, project, plugin, or additional-directory sources. Commands are replaced with [shell command execution disabled by policy] instead of being run. Bundled and managed skills are not affected. Most useful in managed settings where users cannot override it. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "forceRemoteSettingsRefresh": {
      "type": "boolean",
      "description": "(Managed settings only) Block CLI startup until remote managed settings are freshly fetched from the server. If the fetch fails, the CLI exits (fail-closed) rather than continuing with cached settings. When not set, startup continues without waiting for remote settings. See https://code.claude.com/docs/en/server-managed-settings"
    },
    "minimumVersion": {
      "type": "string",
      "description": "Minimum Claude Code version to stay on. Prevents downgrades when switching release channels. See https://code.claude.com/docs/en/settings#available-settings",
      "examples": [
        "2.1.0"
      ],
      "minLength": 1
    },
    "showClearContextOnPlanAccept": {
      "type": "boolean",
      "description": "When true, the plan-approval dialog offers a \"clear context\" option. Defaults to false.",
      "default": false
    },
    "showThinkingSummaries": {
      "type": "boolean",
      "description": "Show thinking summaries in the transcript view (Ctrl+O). Thinking summaries are not generated by default in interactive sessions; set to true to restore. See https://code.claude.com/docs/en/settings#available-settings",
      "default": false
    },
    "skipDangerousModePermissionPrompt": {
      "type": "boolean",
      "description": "Whether the user has accepted the bypass permissions mode dialog. Typically managed by the CLI rather than set by hand."
    },
    "strictPluginOnlyCustomization": {
      "description": "(Managed settings) Block non-plugin customization sources for the listed surfaces. Array form locks specific surfaces (e.g., [\"skills\", \"hooks\"]); true locks all four; false is an explicit no-op. See https://code.claude.com/docs/en/plugins-reference",
      "anyOf": [
        {
          "type": "boolean"
        },
        {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "enum": [
              "skills",
              "agents",
              "hooks",
              "mcp"
            ]
          }
        }
      ]
    },
    "tui": {
      "type": "string",
      "enum": [
        "fullscreen",
        "default"
      ],
      "description": "TUI rendering mode. Use \"fullscreen\" for the flicker-free alt-screen renderer with virtualized scrollback; \"default\" for the classic main-screen renderer. Corresponds to the /tui command. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "viewMode": {
      "type": "string",
      "enum": [
        "default",
        "verbose",
        "focus"
      ],
      "description": "Transcript view mode. \"default\" shows standard interactive view; \"verbose\" shows expanded tool details; \"focus\" shows prompt, one-line tool summaries, and final response only (Ctrl+O toggle). See https://code.claude.com/docs/en/settings#available-settings"
    },
    "useAutoModeDuringPlan": {
      "type": "boolean",
      "description": "When true, apply the auto mode classifier during plan mode to auto-approve safe read-only tool calls while planning. Has no effect unless permissions.defaultMode allows auto. See https://code.claude.com/docs/en/permissions"
    },
    "voiceEnabled": {
      "type": "boolean",
      "description": "Legacy alias for voice.enabled; prefer the voice object. Requires a Claude.ai account. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "wslInheritsWindowsSettings": {
      "type": "boolean",
      "description": "(Windows managed settings only) When true, Claude Code on WSL reads managed settings from the Windows policy chain in addition to /etc/claude-code, with Windows sources taking priority. Only honored when set in the HKLM registry key or C:\\Program Files\\ClaudeCode\\managed-settings.json, both of which require Windows admin to write. For HKCU policy to also apply on WSL, the flag must additionally be set in HKCU itself. Has no effect on native Windows. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "subagentStatusLine": {
      "type": "object",
      "additionalProperties": false,
      "description": "Status line configuration for subagent sessions. See https://code.claude.com/docs/en/statusline#subagent-status-lines",
      "required": [
        "type",
        "command"
      ],
      "properties": {
        "type": {
          "type": "string",
          "const": "command",
          "description": "Must be \"command\""
        },
        "command": {
          "type": "string",
          "description": "Shell command to run for the subagent status line",
          "minLength": 1
        }
      }
    },
    "advisorModel": {
      "type": "string",
      "description": "Model for the server-side advisor tool. Accepts a model alias (\"opus\", \"sonnet\", or \"fable\" on v2.1.170+) or a full model ID. Overridden by the --advisor CLI flag for the session, and blocked when the model is outside the availableModels allowlist. See https://code.claude.com/docs/en/advisor"
    },
    "autoCompactEnabled": {
      "type": "boolean",
      "description": "Automatically compact the conversation when context approaches the limit. Also configurable via the DISABLE_AUTO_COMPACT environment variable. See https://code.claude.com/docs/en/settings#available-settings",
      "default": true
    },
    "disableAgentView": {
      "type": "boolean",
      "description": "(Managed settings) Turn off background agents and the agent view: claude agents, --bg, /background, and the on-demand supervisor. Also configurable via the CLAUDE_CODE_DISABLE_AGENT_VIEW environment variable (set to 1 to disable). See https://code.claude.com/docs/en/agent-view"
    },
    "editorMode": {
      "type": "string",
      "enum": [
        "normal",
        "vim"
      ],
      "description": "Key binding mode for the input prompt: \"normal\" or \"vim\". Appears in /config as Editor mode. See https://code.claude.com/docs/en/terminal-config#edit-prompts-with-vim-keybindings",
      "default": "normal"
    },
    "enforceAvailableModels": {
      "type": "boolean",
      "description": "(Managed settings) Extend the availableModels allowlist to the Default model option (requires v2.1.175+). Requires a non-empty availableModels list; when the account-type default is not in the allowlist, Default resolves to the first allowed entry instead. Has no effect when availableModels is unset or empty. See https://code.claude.com/docs/en/model-config#enforce-the-allowlist-for-the-default-model"
    },
    "fallbackModel": {
      "type": "array",
      "maxItems": 3,
      "items": {
        "type": "string"
      },
      "description": "Fallback model chain tried in order when the primary model is overloaded, unavailable, or returns a non-retryable server error. Capped at three entries after deduplication; accepts model names or aliases, and \"default\" expands to the account-type default. Overridden by the --fallback-model CLI flag for the session. See https://code.claude.com/docs/en/model-config#fallback-model-chains"
    },
    "fileCheckpointingEnabled": {
      "type": "boolean",
      "description": "Snapshot edited files so /rewind can restore them. Also configurable via the CLAUDE_CODE_DISABLE_FILE_CHECKPOINTING environment variable (set to 1 to disable). See https://code.claude.com/docs/en/checkpointing",
      "default": true
    },
    "gcpAuthRefresh": {
      "type": "string",
      "description": "Command to run when GCP credentials are expired or cannot be loaded. The command's output is displayed to the user but interactive input is not supported; it times out after three minutes. See https://code.claude.com/docs/en/google-vertex-ai#advanced-credential-configuration",
      "examples": [
        "gcloud auth application-default login"
      ],
      "minLength": 1
    },
    "managedMcpServers": {
      "type": "array",
      "description": "(Managed settings, third-party Desktop deployments only) MCP server configurations pushed to all users. Each entry specifies the transport and connection details, plus an optional toolPolicy map. Delivered through the managed settings file or MDM. See https://code.claude.com/docs/en/desktop#enterprise-configuration",
      "items": {
        "type": "object",
        "additionalProperties": true
      }
    },
    "skillListingMaxDescChars": {
      "type": "integer",
      "exclusiveMinimum": 0,
      "description": "Per-skill character cap on the combined description and when_to_use text in the skill listing Claude sees each turn. Text longer than this is truncated. See https://code.claude.com/docs/en/skills#skill-descriptions-are-cut-short",
      "default": 1536
    },
    "preferredNotifChannel": {
      "type": "string",
      "enum": [
        "auto",
        "terminal_bell",
        "iterm2",
        "iterm2_with_bell",
        "kitty",
        "ghostty",
        "notifications_disabled"
      ],
      "description": "Method for task-complete and permission-prompt notifications. \"auto\" (default) sends a desktop notification in iTerm2, Ghostty, and Kitty and does nothing in other terminals; \"terminal_bell\" rings the bell in any terminal; \"notifications_disabled\" turns them off. See https://code.claude.com/docs/en/terminal-config#get-a-terminal-bell-or-notification",
      "default": "auto"
    },
    "pluginSuggestionMarketplaces": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "(Managed settings only) Allowlist of marketplace names whose plugins may surface as contextual \"suggested for this directory\" tips in the /plugin Discover tab. No marketplace-declared suggestions surface without this allowlist. The built-in first-party frontend-design tip is unaffected. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "requiredMaximumVersion": {
      "type": "string",
      "description": "(Managed settings only) Maximum Claude Code version allowed to start. If the running version is newer, Claude Code exits at startup with instructions to install an approved version. See https://code.claude.com/docs/en/admin-setup#decide-what-to-enforce"
    },
    "requiredMinimumVersion": {
      "type": "string",
      "description": "(Managed settings only) Minimum Claude Code version required to start. If the running version is older, Claude Code exits at startup rather than only warning. See https://code.claude.com/docs/en/admin-setup#decide-what-to-enforce"
    },
    "respondToBashCommands": {
      "type": "boolean",
      "description": "Whether Claude responds after an input-box ! shell command runs (v2.1.186+). Set to false to add the command output to context without a response. See https://code.claude.com/docs/en/interactive-mode#shell-mode-with--prefix",
      "default": true
    },
    "skillListingBudgetFraction": {
      "type": "number",
      "exclusiveMinimum": 0,
      "maximum": 1,
      "description": "Fraction of the model context window reserved for the skill listing sent to Claude (default 0.01 = 1%). When the listing exceeds this, descriptions are shortened to fit. Also configurable via the SLASH_COMMAND_TOOL_CHAR_BUDGET environment variable (fixed character count). See https://code.claude.com/docs/en/skills#skill-descriptions-are-cut-short",
      "default": 0.01
    },
    "sshConfigs": {
      "type": "array",
      "description": "(Managed settings) Pre-configured SSH connections distributed to Desktop users. See https://code.claude.com/docs/en/desktop#ssh-sessions",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier for this SSH config, used to match configs across settings sources"
          },
          "name": {
            "type": "string",
            "description": "Display name for the SSH connection"
          },
          "sshHost": {
            "type": "string",
            "description": "SSH host in the form \"user@hostname\" or \"hostname\", or a host alias from ~/.ssh/config"
          },
          "sshPort": {
            "type": "integer",
            "description": "SSH port (default 22)"
          },
          "sshIdentityFile": {
            "type": "string",
            "description": "Path to the SSH identity file (private key)"
          },
          "startDirectory": {
            "type": "string",
            "description": "Default working directory on the remote host; supports tilde expansion. Defaults to the remote user home directory"
          }
        },
        "required": [
          "id",
          "name",
          "sshHost"
        ]
      }
    },
    "sshHostAllowlist": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "(Managed settings only) Allowlist restricting Desktop SSH sessions to approved hosts. Patterns are case-insensitive; * matches any host and *.example.com matches example.com and any subdomain. See https://code.claude.com/docs/en/desktop#ssh-sessions"
    },
    "theme": {
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "auto",
            "dark",
            "light",
            "dark-daltonized",
            "light-daltonized",
            "dark-ansi",
            "light-ansi"
          ]
        },
        {
          "type": "string",
          "pattern": "^custom:.+",
          "description": "Reference to a custom theme defined in ~/.claude/themes/, in the form \"custom:<slug>\""
        }
      ],
      "description": "Color theme for the interface: auto, dark, light, the daltonized variants (deuteranopia-friendly), the ansi variants (16-color terminals), or a custom theme reference such as custom:<slug> or custom:<plugin-name>:<slug>. See https://code.claude.com/docs/en/terminal-config#match-the-color-theme",
      "default": "dark"
    },
    "voice": {
      "type": "object",
      "additionalProperties": false,
      "description": "Voice dictation settings: enabled turns dictation on, mode selects \"hold\" or \"tap\", and autoSubmit sends the prompt on key release in hold mode. Written automatically when you run /voice. Requires a Claude.ai account. See https://code.claude.com/docs/en/voice-dictation",
      "properties": {
        "enabled": {
          "type": "boolean",
          "description": "Enable push-to-talk voice dictation input"
        },
        "mode": {
          "type": "string",
          "enum": [
            "hold",
            "tap"
          ],
          "description": "Recording mode: \"hold\" (default) is push-to-talk; \"tap\" taps once to start and again to stop and submit"
        },
        "autoSubmit": {
          "type": "boolean",
          "description": "In hold mode, auto-submit the prompt on key release when the transcript is at least three words long"
        }
      }
    },
    "wheelScrollAccelerationEnabled": {
      "type": "boolean",
      "description": "In fullscreen rendering, accelerate mouse-wheel scroll speed during fast scrolls (v2.1.174+). Set to false for a constant scroll rate per wheel notch. See https://code.claude.com/docs/en/fullscreen#mouse-wheel-scrolling"
    },
    "disableBundledSkills": {
      "type": "boolean",
      "description": "Disable the skills and workflows that ship with Claude Code: bundled skills and workflows are removed entirely, while built-in slash commands like /init stay typable but are hidden from the model. Skills from plugins, .claude/skills/, and .claude/commands/ are unaffected. Also configurable via the CLAUDE_CODE_DISABLE_BUNDLED_SKILLS environment variable. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "awaySummaryEnabled": {
      "type": "boolean",
      "description": "Show a one-line session recap when you return to the terminal after a few minutes away. Set to false (or turn off Session recap in /config) to disable. See https://code.claude.com/docs/en/settings#available-settings",
      "default": true
    },
    "autoScrollEnabled": {
      "type": "boolean",
      "description": "In fullscreen rendering, follow new output to the bottom of the conversation. Appears in /config as Auto-scroll. Permission prompts still scroll into view when this is off. See https://code.claude.com/docs/en/fullscreen",
      "default": true
    },
    "allowAllClaudeAiMcps": {
      "type": "boolean",
      "description": "(Managed settings only) Load claude.ai connectors alongside a deployed managed-mcp.json, which otherwise takes exclusive control and suppresses them. See https://code.claude.com/docs/en/managed-mcp"
    },
    "agentPushNotifEnabled": {
      "type": "boolean",
      "description": "When Remote Control is connected, allow Claude to send proactive push notifications to your phone, for example when a long task finishes. Requires Claude Code v2.1.119 or later. See https://code.claude.com/docs/en/remote-control#mobile-push-notifications",
      "default": false
    },
    "axScreenReader": {
      "type": "boolean",
      "description": "Render screen-reader-friendly output: flat text without decorative borders or animations screen-reader mode always uses the classic renderer, so the tui setting has no effect while it is active. The CLAUDE_AX_SCREEN_READER environment variable and --ax-screen-reader flag take precedence. Requires Claude Code v2.1.181 or later. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "claudeMd": {
      "type": "string",
      "description": "(Managed settings only) CLAUDE.md-style instructions injected as organization-managed memory. Honored only from managed/policy settings. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "disableArtifact": {
      "type": "boolean",
      "description": "Disable the Artifact tool, which publishes session output as a private web page on claude.ai. Also configurable via the CLAUDE_CODE_DISABLE_ARTIFACT environment variable. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "disableAutoMode": {
      "type": "string",
      "enum": [
        "disable"
      ],
      "description": "Set to \"disable\" to prevent auto mode from being activated: removes auto from the Shift+Tab cycle and rejects --permission-mode auto at startup. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "disableClaudeAiConnectors": {
      "type": "boolean",
      "description": "Disable claude.ai MCP connectors so they are not auto-fetched or connected. A value of true in any settings source takes precedence. Requires Claude Code v2.1.182 or later. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "disableRemoteControl": {
      "type": "boolean",
      "description": "Disable Remote Control: blocks claude remote-control, the --remote-control flag, auto-start, and the in-session toggle. Requires Claude Code v2.1.128 or later. See https://code.claude.com/docs/en/remote-control"
    },
    "disableWorkflows": {
      "type": "boolean",
      "description": "Disable dynamic workflows and bundled workflow commands. Also configurable via the CLAUDE_CODE_DISABLE_WORKFLOWS environment variable. See https://code.claude.com/docs/en/settings#available-settings",
      "default": false
    },
    "footerLinksRegexes": {
      "type": "array",
      "description": "Render extra clickable badges in the footer when a regex matches turn output (tool results and assistant responses). Read from user, --settings flag, and managed settings only; ignored in project and local settings. Requires Claude Code v2.1.176 or later. See https://code.claude.com/docs/en/settings#available-settings",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "type": {
            "type": "string",
            "const": "regex",
            "description": "Config variant; \"regex\" matches turn output and builds a URL from named capture groups"
          },
          "pattern": {
            "type": "string",
            "description": "Regex matched against turn output"
          },
          "url": {
            "type": "string",
            "description": "Link target; {name} placeholders are filled from named regex capture groups"
          },
          "label": {
            "type": "string",
            "description": "Badge text; {name} placeholders filled from named capture groups, defaults to the full match"
          }
        },
        "required": [
          "pattern",
          "url"
        ]
      }
    },
    "inputNeededNotifEnabled": {
      "type": "boolean",
      "description": "When Remote Control is connected, send a push notification to your phone when a permission prompt or question is waiting for input. Requires Claude Code v2.1.119 or later. See https://code.claude.com/docs/en/settings#available-settings",
      "default": false
    },
    "policyHelper": {
      "type": "object",
      "additionalProperties": false,
      "description": "Admin-deployed executable that computes managed settings dynamically at startup. Honored only from MDM or the system managed-settings.json. Requires Claude Code v2.1.136 or later. See https://code.claude.com/docs/en/settings#available-settings",
      "properties": {
        "path": {
          "type": "string",
          "description": "Absolute path to the policy helper executable"
        },
        "timeoutMs": {
          "type": "integer",
          "description": "How long in milliseconds to wait for the helper before treating the run as failed"
        },
        "refreshIntervalMs": {
          "description": "How often in milliseconds to re-run the helper in the background; set to 0 to disable refresh, or to at least 60000",
          "anyOf": [
            {
              "type": "integer",
              "const": 0
            },
            {
              "type": "integer",
              "minimum": 60000
            }
          ]
        }
      },
      "required": [
        "path"
      ]
    },
    "remoteControlAtStartup": {
      "type": "boolean",
      "description": "Connect Remote Control automatically when each interactive session starts. true = always, false = never, unset = organization default. Requires Claude Code v2.1.119 or later. See https://code.claude.com/docs/en/remote-control#enable-remote-control-for-all-sessions"
    },
    "syntaxHighlightingDisabled": {
      "type": "boolean",
      "description": "Disable syntax highlighting in diffs, code blocks, and file previews. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "verbose": {
      "type": "boolean",
      "description": "Show full tool output instead of truncated summaries. The --verbose flag overrides this for a single session. Requires Claude Code v2.1.119 or later. See https://code.claude.com/docs/en/settings#available-settings",
      "default": false
    },
    "workflowKeywordTriggerEnabled": {
      "type": "boolean",
      "description": "Whether including the keyword \"ultracode\" in a prompt triggers a dynamic workflow. Requires Claude Code v2.1.157 or later. See https://code.claude.com/docs/en/settings#available-settings",
      "default": true
    },
    "askUserQuestionTimeout": {
      "type": "string",
      "description": "Idle time before an unanswered AskUserQuestion dialog auto-continues with whatever options you had already selected. Accepts \"60s\", \"5m\", \"10m\", or \"never\" (default: \"never\", which waits until you answer). Appears in /config as Question auto-continue timeout, which writes this key to user settings. Not read from project or local settings. Requires Claude Code v2.1.200 or later. See https://code.claude.com/docs/en/settings#available-settings",
      "enum": [
        "60s",
        "5m",
        "10m",
        "never"
      ],
      "default": "never"
    },
    "teammateDefaultModel": {
      "type": [
        "string",
        "null"
      ],
      "description": "Default model for agent team teammates when the spawn prompt does not specify one. Set to a model alias such as \"sonnet\", or null to inherit the lead's current /model selection. Appears in /config as Default teammate model. See https://code.claude.com/docs/en/agent-teams",
      "examples": [
        "sonnet"
      ]
    },
    "workflowSizeGuideline": {
      "type": "string",
      "description": "Sets the agent count Claude aims for in the dynamic workflows it writes. Claude Code sends the value to Claude as advice, not an enforced cap. Accepts \"unrestricted\" (default, which sends no guideline), \"small\", \"medium\", or \"large\". Appears in /config as Dynamic workflow size, and can be set with /config workflowSizeGuideline=small. Requires Claude Code v2.1.202 or later. On v2.1.203 or later the guideline's agent count also replaces the default threshold for the Large workflow warning. See https://code.claude.com/docs/en/workflows#set-a-size-guideline",
      "enum": [
        "unrestricted",
        "small",
        "medium",
        "large"
      ],
      "default": "unrestricted"
    },
    "enableArtifact": {
      "type": "boolean",
      "description": "Enable or disable the Artifact tool for this user. When unset, the default follows the feature's availability for your account. The Artifacts row in /config writes this key. A managed disableArtifact and your organization's admin setting take precedence, and the key is ignored in project and local settings (.claude/settings.json, .claude/settings.local.json), which a repository could otherwise commit. Requires Claude Code v2.1.196 or later. See https://code.claude.com/docs/en/artifacts"
    },
    "permissionExplainerEnabled": {
      "type": "boolean",
      "description": "Show a model-generated explanation of the command when you press Ctrl+E on a Bash or PowerShell permission prompt (default: true). Set to false to turn the shortcut off. See https://code.claude.com/docs/en/permissions#permission-system",
      "default": true
    },
    "diffTool": {
      "type": "string",
      "description": "Where to display file diffs when an IDE is connected: \"auto\" (default) opens diffs in the IDE's diff viewer, \"terminal\" keeps them in the terminal. Appears in /config as Diff tool only when Claude Code is connected to a VS Code or JetBrains IDE. See https://code.claude.com/docs/en/settings#global-config-settings",
      "enum": [
        "auto",
        "terminal"
      ],
      "default": "auto"
    },
    "externalEditorContext": {
      "type": "boolean",
      "description": "Prepend Claude's previous response as #-commented context when you open the external editor with Ctrl+G (default: false). Appears in /config as Show last response in external editor. See https://code.claude.com/docs/en/settings#global-config-settings",
      "default": false
    },
    "autoConnectIde": {
      "type": "boolean",
      "description": "Automatically connect to a running IDE when Claude Code starts from an external terminal (default: false). Appears in /config as Auto-connect to IDE (external terminal) when running outside a VS Code or JetBrains terminal. Also configurable via the CLAUDE_CODE_AUTO_CONNECT_IDE environment variable, which overrides this when set. See https://code.claude.com/docs/en/settings#global-config-settings",
      "default": false
    },
    "autoInstallIdeExtension": {
      "type": "boolean",
      "description": "Automatically install the Claude Code IDE extension when running from a VS Code terminal (default: true). Appears in /config as Auto-install IDE extension when running inside a VS Code or JetBrains terminal. You can also set the CLAUDE_CODE_IDE_SKIP_AUTO_INSTALL environment variable to 1. See https://code.claude.com/docs/en/settings#global-config-settings",
      "default": true
    },
    "emojiCompletionEnabled": {
      "type": "boolean",
      "description": "Show emoji suggestions when you type : plus a shortcode in the prompt input, and replace a completed shortcode such as :heart: with its emoji (default: true). Set to false to disable both. Requires Claude Code v2.1.217 or later. See https://code.claude.com/docs/en/interactive-mode#emoji-shortcodes",
      "default": true
    },
    "vimInsertModeRemaps": {
      "type": "object",
      "description": "Map two-key INSERT-mode sequences to Escape in vim editor mode. Each key is exactly two printable characters typed in sequence, and \"<Esc>\" is the only supported target; other entries are ignored. Read from user, --settings flag, and managed settings only, so a repository's checked-in settings cannot remap your keystrokes. Has no effect unless editorMode is \"vim\". Requires Claude Code v2.1.208 or later. See https://code.claude.com/docs/en/interactive-mode#remap-insert-mode-key-sequences",
      "propertyNames": {
        "pattern": "^..$"
      },
      "additionalProperties": {
        "type": "string",
        "description": "Remap target. \"<Esc>\" is the only supported value; other values are ignored"
      },
      "examples": [
        {
          "jj": "<Esc>"
        }
      ]
    },
    "processWrapper": {
      "type": "string",
      "description": "Corporate launcher command placed in front of the background processes Claude Code starts. Honored from managed settings, a --settings file, and user settings only; the CLAUDE_CODE_PROCESS_WRAPPER environment variable takes precedence when both are set. Requires Claude Code v2.1.210 or later. See https://code.claude.com/docs/en/corporate-launcher",
      "examples": [
        "/opt/corp/launcher --profile claude"
      ]
    },
    "forceLoginGatewayUrl": {
      "type": "string",
      "description": "Pre-fills and locks the gateway URL on the /login Cloud gateway screen. Either this key or forceLoginMethod: \"gateway\" surfaces that screen; set both so the URL is filled in. Honored only at the managed policy tier; ignored in user and project settings. See https://code.claude.com/docs/en/claude-apps-gateway#set-the-gateway-url",
      "examples": [
        "https://claude-gateway.example.com"
      ]
    },
    "disableSideloadFlags": {
      "type": "boolean",
      "description": "(Managed settings only) Reject the --plugin-dir, --plugin-url, --agents, and --mcp-config CLI flags at startup, which users could otherwise pass to bypass strictKnownMarketplaces for a single run. Also rejects these flags from any surface that spawns the CLI with them internally, currently Cowork local sessions in the desktop app. A --mcp-config whose servers are all in-process type: \"sdk\" entries is still accepted, so the Agent SDK and VS Code extension keep working. Does not block claude mcp add, .mcp.json, or SDK setMcpServers(); pair with allowedMcpServers for per-server MCP control. Requires Claude Code v2.1.193 or later. See https://code.claude.com/docs/en/settings#available-settings"
    },
    "browserExternalPageTools": {
      "type": "string",
      "description": "(Managed settings only) Set to \"disabled\" to prevent Claude from using tools to read or act on external pages in the desktop app's Browser pane. Users can still navigate to external sites themselves, and local dev server previews are unaffected. See https://code.claude.com/docs/en/desktop#browse-external-sites",
      "enum": [
        "disabled"
      ]
    },
    "disableBrowserExternalNavigation": {
      "type": "boolean",
      "description": "(Managed settings only) Set to true to turn off external browsing in the desktop app's Browser pane. Neither users nor Claude can navigate to external sites, and localhost dev server previews are unaffected. The value must be the JSON boolean true; the string \"true\" is ignored. See https://code.claude.com/docs/en/desktop#browse-external-sites"
    },
    "disableMobileSimulatorTools": {
      "type": "boolean",
      "description": "(Managed settings only) Set to true to block Claude's tools for the desktop app's iOS Simulator pane. Users keep manual use of the pane; only Claude's access is removed. The value must be the JSON boolean true; any other value is ignored, and a malformed value such as \"true\" or 1 logs a warning. See https://code.claude.com/docs/en/desktop-ios-simulator#turn-off-simulator-access"
    },
    "requireCoworkFullVmSandbox": {
      "type": "boolean",
      "description": "(Managed settings only) Run Claude's tools inside an isolated virtual machine instead of on your Mac. Disables the desktop app's iOS Simulator pane and Claude's simulator tools entirely, so the pane cannot attach a device while it is set. See https://code.claude.com/docs/en/desktop-ios-simulator#turn-off-simulator-access"
    }
  },
  "title": "Claude Code Settings"
}
