        },
        "description": {
          "description": "Human-facing role documentation used in spawn tool guidance. Required unless supplied by the referenced agent role file.",
          "type": "string"
        },
        "nickname_candidates": {
          "description": "Candidate nicknames for agents spawned with this role.",
          "items": {
            "type": "string"
          },
          "type": "array"
        }
