        "interrupt_message": {
          "description": "Whether to record a model-visible message when an agent turn is interrupted. Defaults to true.",
          "type": "boolean"
        },
        "job_max_runtime_seconds": {
          "description": "Default maximum runtime in seconds for agent job workers.",
          "format": "uint64",
          "minimum": 1.0,
          "type": "integer"
        },
        "max_depth": {
          "description": "Maximum nesting depth allowed for spawned agent threads. Root sessions start at depth 0.",
          "format": "int32",
          "minimum": 1.0,
          "type": "integer"
        },
        "max_threads": {
          "description": "Maximum number of agent threads that can be open concurrently. When unset, no limit is enforced.",
          "format": "uint",
          "minimum": 1.0,
          "type": "integer"
        }
      },
      "type": "object"
    },
    "AltScreenMode": {
      "description": "Controls whether the TUI uses the terminal's alternate screen buffer.\n\n- `auto` (default): Use alternate screen mode. - `always`: Always use alternate screen mode. - `never`: Never use alternate screen mode. Runs in inline mode, preserving scrollback.\n\nThe CLI flag `--no-alt-screen` can override this setting at runtime.",
      "oneOf": [
        {
          "description": "Use alternate screen mode.",
          "enum": [
            "auto"
          ],
          "type": "string"
        },
        {
          "description": "Always use alternate screen mode.",
          "enum": [
            "always"
          ],
          "type": "string"
        },
        {
          "description": "Never use alternate screen (inline mode only).",
          "enum": [
            "never"
          ],
          "type": "string"
        }
      ]
    },
    "AnalyticsConfigToml": {
      "additionalProperties": false,
      "description": "Analytics settings loaded from config.toml. Fields are optional so we can apply defaults.",
