        "auto_review",
        "guardian_subagent"
      ],
      "type": "string"
    },
    "AppsConfigToml": {
      "additionalProperties": {
        "$ref": "#/definitions/AppConfig"
      },
      "description": "App/connector settings loaded from `config.toml`.",
      "properties": {
