main() {
  parse_options "$@"
  init_scratch
  if [[ "${action}" == configure ]]; then
    collect_endpoint
    confirm_gateway_reachable
  fi
  adapter="${harness//-/_}"
  "${adapter}_prepare"
  if [[ "${action}" != configure ]]; then
    overwrite=1
    switch_begin
    switch_stage_local
    switch_finish
    commit_transaction
    ui_title "${harness} gateway ${action} completed locally"
    report_transaction
    return
  fi
  confirm_existing_setup
  switch_begin
  load_stored_key
  choose_key
  if [[ "${harness}" != omp ]]; then native_validate_client; fi
  validate_gateway
  "${adapter}_stage"
  stage_key
  switch_finish
  commit_transaction
  if [[ "${harness}" == omp ]]; then omp_report; else native_report; fi
}
